import{_ as n,o as s,c as e,f as a,a as o}from"./app-v4ODCOL5.js";const t={},p=o(`<h2 id="第-17-章-前端工程化与构建工具链" tabindex="-1"><a class="header-anchor" href="#第-17-章-前端工程化与构建工具链" aria-hidden="true">#</a> 第 17 章 前端工程化与构建工具链</h2><h3 id="q1-前端工程化到底要解决什么问题-别只答-用-webpack-打包" tabindex="-1"><a class="header-anchor" href="#q1-前端工程化到底要解决什么问题-别只答-用-webpack-打包" aria-hidden="true">#</a> Q1 前端工程化到底要解决什么问题？别只答&quot;用 webpack 打包&quot;</h3><p><strong>考察点</strong>：考你是否把工程化理解成一套体系而不是一个工具。能按&quot;开发体验、协作规范、构建、发布、质量&quot;五个维度说清痛点与手段才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：前端工程化的本质是把&quot;多人协作、长期维护、频繁发布&quot;带来的重复劳动和人为失误，交给工具链和约定去消除；它至少覆盖开发体验、协作规范、构建、发布、质量这五块。</p></blockquote><ol><li>开发体验：模块化拆分、TypeScript 类型提示、路径别名、本地热更新（Hot Module Replacement，HMR），目标是&quot;改一行代码，一秒内看到效果&quot;。</li><li>协作规范：统一的目录结构、代码风格（ESLint/Prettier）、提交信息规范、分支模型，目标是让代码评审只关注逻辑，不争论空格和分号。</li><li>构建：把浏览器不认识的语法和资源（TS、Sass、图片、Vue 单文件）转成可运行产物，并做压缩、拆分、兼容处理。</li><li>发布：环境变量注入、产物指纹、CDN 上传与缓存刷新、灰度与回滚，目标是&quot;上线可预期、出事能退&quot;。</li><li>质量：静态检查、单元/集成/E2E 测试、CI 流水线卡口，目标是把问题拦在合并前而不是线上。</li><li>落地载体：脚手架与模板工程把上面这些一次性固化下来，新项目 <code>create</code> 出来就自带 lint、HMR、多环境、CI 和 Docker 配置，避免每个项目重新踩坑。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：小项目需要这么重吗？答：工程化的成本要和团队规模、项目寿命匹配。个人项目直接 Vite 默认配置就够，硬上 monorepo 与多层 CI 反而是负担。</li><li>陷阱：把工程化等同于&quot;会写 webpack.config.js&quot;。工具只是手段，面试官想听的是&quot;哪个环节的什么痛点被消除了&quot;。</li><li>追问：你们项目的脚手架是怎么搭的？答：用 <code>create-vue</code> 或自研 CLI（commander + prompts 交互 + degit 拉模板）生成，模板里预置别名、lint、husky、多环境与 CI；关键是要有人维护模板版本，否则&quot;模板腐化&quot;成没人敢用的老配置。</li></ul><h3 id="q2-webpack-那几个核心配置项-各自管什么" tabindex="-1"><a class="header-anchor" href="#q2-webpack-那几个核心配置项-各自管什么" aria-hidden="true">#</a> Q2 Webpack 那几个核心配置项，各自管什么？</h3><p><strong>考察点</strong>：考 <code>entry</code>/<code>output</code>/<code>loader</code>/<code>plugin</code>/<code>mode</code>/<code>resolve</code>/<code>devServer</code> 的职责边界，能否一眼说出改需求该动哪一项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>entry</code> 决定从哪开始找依赖，<code>output</code> 决定产物写到哪、叫什么名字，<code>loader</code> 负责把非 JS 模块翻译成模块，<code>plugin</code> 负责在编译生命周期上做任意扩展，<code>mode</code> 决定内置优化开关，<code>resolve</code> 决定模块怎么找，<code>devServer</code> 负责本地服务与热更新。</p></blockquote><ol><li><code>entry</code>：依赖图（Dependency Graph）起点，可以是字符串、数组（多入口合并成一个 chunk）或对象（多页应用多入口），也可以是函数做动态入口。</li><li><code>output</code>：<code>path</code>（绝对路径）、<code>filename</code>（支持 <code>[name]</code>/<code>[contenthash]</code> 占位符）、<code>publicPath</code>（产物在浏览器里的公共访问前缀，配 CDN 或子路径部署必改）、<code>clean: true</code>（构建前清空目录）、asset 相关命名。</li><li><code>module.rules</code> 的 <code>loader</code> 与 <code>plugins</code> 的 <code>plugin</code>：webpack 只原生理解 JS/JSON，其余资源全靠 loader 翻译，规则写 <code>test</code> + <code>include/exclude</code> + <code>use</code>（<code>include</code> 精确到 <code>src</code> 是常见提速手段）；plugin 是 <code>new</code> 出来的实例，通过钩子干预编译流程，能做抽离 CSS、注入全局变量、生成 HTML 这类 loader 做不到的事。</li><li><code>mode</code>：<code>development</code>/<code>production</code>/<code>none</code>。<code>production</code> 会自动把 <code>process.env.NODE_ENV</code> 设为 <code>production</code>，并默认开启压缩、tree-shaking（摇树优化）等；不写会警告且拿不到内置优化。</li><li><code>resolve</code>：<code>extensions</code>（省略后缀的补齐顺序，越少越快）、<code>alias</code>（路径别名）、<code>modules</code>（查找目录）、<code>mainFields</code>（决定优先用 <code>module</code> 还是 <code>main</code>，直接影响 tree-shaking）。</li><li><code>devServer</code>：基于 webpack-dev-server，产物放内存不落盘，提供 HMR、<code>proxy</code> 代理、<code>historyApiFallback</code>（支持 history 路由）、<code>static</code> 静态目录。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// webpack.config.js 常用骨架</span>
module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">mode</span><span class="token operator">:</span> <span class="token string">&#39;production&#39;</span><span class="token punctuation">,</span>
  <span class="token literal-property property">entry</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">app</span><span class="token operator">:</span> <span class="token string">&#39;./src/main.js&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">output</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">path</span><span class="token operator">:</span> path<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>__dirname<span class="token punctuation">,</span> <span class="token string">&#39;dist&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token literal-property property">filename</span><span class="token operator">:</span> <span class="token string">&#39;[name].[contenthash:8].js&#39;</span><span class="token punctuation">,</span>
            <span class="token literal-property property">publicPath</span><span class="token operator">:</span> <span class="token string">&#39;/&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">clean</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">resolve</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">extensions</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;.js&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;.ts&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;.vue&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token literal-property property">alias</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;@&#39;</span><span class="token operator">:</span> path<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>__dirname<span class="token punctuation">,</span> <span class="token string">&#39;src&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">module</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">rules</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token literal-property property">test</span><span class="token operator">:</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">\\.css$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">,</span> <span class="token literal-property property">use</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;style-loader&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;css-loader&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">plugins</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token keyword">new</span> <span class="token class-name">HtmlWebpackPlugin</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">template</span><span class="token operator">:</span> <span class="token string">&#39;./public/index.html&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>publicPath</code> 和 <code>output.path</code> 的区别？答：<code>path</code> 是磁盘上的输出目录，<code>publicPath</code> 是浏览器请求产物时的 URL 前缀，两者没有关系；上 CDN 或部署到子路径时最容易在这翻车。</li><li>陷阱：<code>[hash]</code> 与 <code>[contenthash]</code> 混用。<code>[hash]</code> 是整个构建的哈希，改一个文件全部文件名变，缓存全失效；生产必须用 <code>[contenthash]</code>。</li><li>追问：为什么线上白屏但本地正常？先看 <code>publicPath</code>/<code>base</code> 与实际部署路径是否一致，再看 <code>index.html</code> 是否被 CDN 长缓存。</li></ul><h3 id="q3-loader-和-plugin-有什么区别-执行顺序是怎样的" tabindex="-1"><a class="header-anchor" href="#q3-loader-和-plugin-有什么区别-执行顺序是怎样的" aria-hidden="true">#</a> Q3 loader 和 plugin 有什么区别？执行顺序是怎样的？</h3><p><strong>考察点</strong>：考职责差异与 loader 链的顺序规则，这题答混基本会被判定为&quot;只会抄配置&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：loader 是&quot;文件到模块&quot;的翻译器，工作在模块级别，链式执行且从右到左；plugin 是&quot;构建过程的插桩&quot;，通过钩子作用于整个编译生命周期，能做任意事。</p></blockquote><ol><li>作用对象不同：loader 处理单个文件（或模块）的内容转换，输入源码、输出新代码；plugin 拿到的是 <code>compiler</code>/<code>compilation</code> 对象，能改产物、加文件、改优化策略。</li><li>配置位置不同：loader 写在 <code>module.rules</code> 里，按文件类型匹配；plugin 写在 <code>plugins</code> 数组里，<code>new</code> 实例化后由 webpack 调用其 <code>apply</code> 方法。</li><li>loader 执行顺序：数组里<strong>从右到左</strong>（配置写成分层时是从下到上）。<code>use: [&#39;style-loader&#39;, &#39;css-loader&#39;, &#39;sass-loader&#39;]</code> 的真实顺序是 sass → css → style。</li><li>为什么这个顺序：前一个 loader 的输出是后一个的输入，所以必须&quot;先编译后应用&quot;。<code>sass-loader</code> 产出 CSS 字符串，<code>css-loader</code> 把它变成 JS 模块，<code>style-loader</code> 再把样式注入 <code>&lt;style&gt;</code>。</li><li>loader 还有 pitching 阶段：从左到右执行 <code>pitch</code> 方法，用于提前拦截（<code>style-loader</code> 就靠 pitch 提前返回注入脚本）。不写 pitch 时可以忽略这个细节。</li><li>一个 loader 只能做一件事，组合出能力；plugin 靠 tapable 钩子（后面单开一题）串进流程。判断标准：<strong>&quot;能不能只靠一个文件的内容算出结果&quot;</strong>，能就是 loader。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 顺序演示：sass-loader → css-loader → style-loader</span>
<span class="token punctuation">{</span> <span class="token literal-property property">test</span><span class="token operator">:</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">\\.scss$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">,</span> <span class="token literal-property property">use</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;style-loader&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;css-loader&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;sass-loader&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span>

<span class="token comment">// plugin：与文件类型无关，直接作用于编译过程</span>
<span class="token literal-property property">plugins</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token keyword">new</span> <span class="token class-name">MiniCssExtractPlugin</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">filename</span><span class="token operator">:</span> <span class="token string">&#39;[name].[contenthash:8].css&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>css-loader</code> 能不能用 plugin 代替？答：不行。抽取 CSS 到独立文件是 plugin 的活（MiniCssExtractPlugin），但把 CSS 代码解析成模块、处理 <code>@import</code> 和 <code>url()</code> 必须靠 loader，两者是配合关系。</li><li>陷阱：把 <code>style-loader</code> 写在数组最后一个。那样 <code>css-loader</code> 收到的是注入脚本的源码而不是 CSS 模块，直接报错。</li><li>追问：loader 可以是异步的吗？答：可以，调用 <code>this.async()</code> 拿到 callback，或直接返回 Promise；访问文件、请求网络的 loader 必须异步。</li></ul><h3 id="q4-常见-loader-有哪些-让你手写一个-loader-怎么写" tabindex="-1"><a class="header-anchor" href="#q4-常见-loader-有哪些-让你手写一个-loader-怎么写" aria-hidden="true">#</a> Q4 常见 loader 有哪些？让你手写一个 loader 怎么写？</h3><p><strong>考察点</strong>：考 loader 清单的广度，以及是否真的理解 loader 函数的入参出参和 <code>this</code> 上的上下文 API。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：loader 就是一个接收源码、返回新源码的函数，可以同步返回、调 <code>this.async()</code> 回调或返回 Promise；写自定义 loader 的关键是拿到 <code>this</code> 上的上下文（资源路径、配置项、callback）并把 source map 正确串下去。</p></blockquote><ol><li>常用清单：语法类 <code>babel-loader</code>/<code>ts-loader</code>/<code>esbuild-loader</code>/<code>swc-loader</code>；样式类 <code>style-loader</code>、<code>css-loader</code>、<code>postcss-loader</code>、<code>sass-loader</code>/<code>less-loader</code>；框架类 <code>vue-loader</code>；模板类 <code>html-loader</code>；并行加速 <code>thread-loader</code>。</li><li>Webpack 5 用资源模块（Asset Modules）替代了 <code>file-loader</code>/<code>url-loader</code>/<code>raw-loader</code>：<code>type: &#39;asset/resource&#39;</code> 输出文件，<code>asset/inline</code> 转 DataURL，<code>asset/source</code> 读成字符串，<code>asset</code> 按体积阈值自动二选一。</li><li>loader 函数签名：<code>function (source, inputMap, meta)</code>，同步时 <code>return</code>（或返回 <code>[code, map, meta]</code>），异步时 <code>const cb = this.async()</code> 再 <code>cb(null, code, map, meta)</code>。</li><li><code>this</code> 上的常用 API：<code>this.resourcePath</code>（当前文件绝对路径）、<code>this.getOptions()</code>（取 loader 配置，替代已废弃的 <code>loader-utils</code>）、<code>this.addDependency()</code>（把额外文件加入 watch）、<code>this.emitFile()</code>（产出文件）、<code>this.cacheable()</code>。</li><li>想用现成编译器转代码，直接在里面调 babel/esbuild 即可，但要把 <code>inputSourceMap</code> 传进去、把新的 map 传出来，否则断点位置会错。</li><li>调试手段：<code>this.emitWarning/emitError</code> 报错，<code>this.getLogger()</code> 打日志；写好后用 <code>resolveLoader.modules</code> 或 <code>resolveLoader.alias</code> 让本地 loader 能被找到。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// loaders/strip-console.js：删掉源码里的 console 调用</span>
module<span class="token punctuation">.</span><span class="token function-variable function">exports</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">source<span class="token punctuation">,</span> inputMap</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> cb <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">async</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> <span class="token punctuation">{</span> code<span class="token punctuation">,</span> map <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;esbuild&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">transformSync</span><span class="token punctuation">(</span>source<span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">loader</span><span class="token operator">:</span> <span class="token string">&#39;js&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">minify</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span> <span class="token literal-property property">sourcemap</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token literal-property property">sourcefile</span><span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>resourcePath<span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">addDependency</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>resourcePath<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 参与 watch 与缓存失效</span>
  <span class="token function">cb</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">,</span> code<span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">console\\.log\\([^)]*\\);?</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> map<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// webpack.config.js 里启用本地 loader</span>
<span class="token literal-property property">resolveLoader</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">modules</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;node_modules&#39;</span><span class="token punctuation">,</span> path<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>__dirname<span class="token punctuation">,</span> <span class="token string">&#39;loaders&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：自定义 loader 会被缓存吗？答：会。webpack 5 的持久化缓存按 loader、配置、文件内容算哈希；改了 loader 代码要重启或改 <code>buildDependencies</code>，否则旧结果被复用。</li><li>陷阱：手写 loader 时直接改 <code>source</code> 而不是返回新值，或者返回值不是字符串/<code>Buffer</code>，报 &quot;loader must return a string or Buffer&quot;。</li><li>追问：为什么 <code>babel-loader</code> 一定要配 <code>exclude: /node_modules/</code>？答：否则会把成千上万个依赖也用 Babel 转一遍，构建时间翻几倍；但需要转某个依赖时，可以用 <code>include</code> 精确放行，或用 <code>transpileDependencies</code> 白名单。</li></ul><h3 id="q5-plugin-的原理是什么-说说-tapable-和编译生命周期钩子" tabindex="-1"><a class="header-anchor" href="#q5-plugin-的原理是什么-说说-tapable-和编译生命周期钩子" aria-hidden="true">#</a> Q5 plugin 的原理是什么？说说 tapable 和编译生命周期钩子</h3><p><strong>考察点</strong>：考插件机制的本质。能说出&quot;webpack 自身就是 tapable 的主控台上的插件集合&quot;并列出关键钩子，才算到深挖档。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：webpack 的编译过程暴露成一系列 tapable 钩子，plugin 就是一个带 <code>apply(compiler)</code> 方法的类，在钩子上注册回调从而干预构建；<code>compiler</code> 代表整个生命周期，<code>compilation</code> 代表一次构建。</p></blockquote><ol><li>骨架：<code>Compiler</code>（全局唯一，管理配置、watch、输出）与 <code>Compilation</code>（每次编译新建，持有模块图、chunk 图、assets）。webpack 内部几乎所有功能都是插件，配置文件里的 <code>plugins</code> 只是额外的。</li><li>tapable 提供 9 类钩子：同步的 <code>SyncHook</code>/<code>SyncBailHook</code>/<code>SyncWaterfallHook</code>/<code>SyncLoopHook</code>；异步的 <code>AsyncParallelHook</code>/<code>AsyncParallelBailHook</code> 与 <code>AsyncSeriesHook</code>/<code>AsyncSeriesBailHook</code>/<code>AsyncSeriesWaterfallHook</code>。</li><li>注册方式必须与钩子类型匹配：同步用 <code>tap</code>，异步回调式用 <code>tapAsync</code>（收 <code>(…args, callback)</code>），Promise 式用 <code>tapPromise</code>（返回 Promise），否则直接报错。</li><li>关键生命周期（<code>compiler.hooks</code>）：<code>environment</code> → <code>entryOption</code> → <code>afterPlugins</code> → <code>compile</code> → <code>make</code>（开始构建模块）→ <code>emit</code>（写产物前）→ <code>afterEmit</code> → <code>done</code>；<code>compilation.hooks</code>：<code>buildModule</code>/<code>succeedModule</code>（模块级）、<code>optimizeModules</code>、<code>optimizeChunks</code>、<code>processAssets</code>（改产物，最常用）、<code>afterSeal</code>。</li><li>改产物的现代写法：<code>compilation.hooks.processAssets.tap({ name, stage: Compilation.PROCESS_ASSETS_STAGE_ADDITIONAL }, (assets) =&gt; {...})</code>，用 stage 控制与其它插件的先后；<code>compiler.hooks.emit</code> 是老写法，仍可用但时机偏晚。</li><li>写插件模板：<code>class MyPlugin { constructor(options){} apply(compiler){ compiler.hooks.done.tap(&#39;MyPlugin&#39;, (stats) =&gt; {...}) } }</code>。<code>apply</code> 由 webpack 在初始化阶段调用，这也是为什么插件必须 <code>new</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 统计产物文件数的插件</span>
<span class="token keyword">class</span> <span class="token class-name">SizeReportPlugin</span> <span class="token punctuation">{</span>
  <span class="token function">apply</span><span class="token punctuation">(</span><span class="token parameter">compiler</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    compiler<span class="token punctuation">.</span>hooks<span class="token punctuation">.</span>done<span class="token punctuation">.</span><span class="token function">tap</span><span class="token punctuation">(</span><span class="token string">&#39;SizeReportPlugin&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">stats</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
      <span class="token keyword">const</span> <span class="token punctuation">{</span> assets <span class="token punctuation">}</span> <span class="token operator">=</span> stats<span class="token punctuation">.</span><span class="token function">toJson</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">assets</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token keyword">const</span> total <span class="token operator">=</span> assets<span class="token punctuation">.</span><span class="token function">reduce</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">sum<span class="token punctuation">,</span> a</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> sum <span class="token operator">+</span> a<span class="token punctuation">.</span>size<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;产物总大小：&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span>total <span class="token operator">/</span> <span class="token number">1024</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toFixed</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;KB&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：watch 模式下 <code>compiler</code> 会重建吗？答：不会，<code>compiler</code> 只有一个，每次文件变更产生新的 <code>compilation</code>；所以插件里缓存跨越多次编译的数据要挂在 <code>compiler</code> 上，而单次构建的状态挂在 <code>compilation</code> 上。</li><li>陷阱：用 <code>tap</code> 注册 <code>AsyncSeriesHook</code> 后在回调里做异步操作却不返回 Promise，webpack 会在你操作完成前就继续往下走，产物时有时无。</li><li>追问：想在产物里追加一行注释怎么最快？答：<code>compilation.emitAsset</code>/<code>updateAsset</code> 比直接操作 <code>compilation.assets</code> 对象更安全，后者在 webpack 5 已被限制写操作。</li></ul><h3 id="q6-webpack-从敲下-npm-run-build-到产出文件-中间发生了什么" tabindex="-1"><a class="header-anchor" href="#q6-webpack-从敲下-npm-run-build-到产出文件-中间发生了什么" aria-hidden="true">#</a> Q6 Webpack 从敲下 <code>npm run build</code> 到产出文件，中间发生了什么？</h3><p><strong>考察点</strong>：考完整构建流程的三段式（初始化 → 编译 → 输出），能讲到模块图与 chunk 图两个数据结构的层次就到位了。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：读配置建 <code>Compiler</code> 并挂插件是初始化，从 entry 出发用 loader 转模块、递归解析依赖建模块图是编译，把模块图按规则切成 chunk、优化、生成 assets 写盘是输出。</p></blockquote><ol><li>初始化：合并配置（<code>webpack.config.js</code> → 命令行参数 → 默认值），创建 <code>Compiler</code> 实例，遍历 <code>plugins</code> 调用各自的 <code>apply(compiler)</code>，把回调挂到钩子上；如果开了 <code>cache.type: &#39;filesystem&#39;</code>，此时读取磁盘缓存。</li><li>编译入口：<code>compiler.compile</code> → <code>make</code> 钩子 → 从 <code>entry</code> 生成入口模块，交给 <code>NormalModuleFactory</code> 处理。</li><li>解析模块：用 enhanced-resolve 按 <code>resolve</code> 规则把 <code>import &#39;./a&#39;</code> 变成绝对路径（依次尝试 <code>extensions</code>、读 <code>package.json</code> 的 <code>mainFields</code>），命中缓存就不再解析。</li><li>转换模块：把文件内容按 <code>module.rules</code> 依次交给 loader 链，然后用 acorn 解析成 AST，找出 <code>import</code>/<code>require</code>/<code>import()</code> 作为依赖，<strong>递归</strong>处理，最终得到模块图（ModuleGraph）。</li><li>封装（seal）与优化：根据入口与 <code>import()</code> 边界把模块分配到 chunk，形成 chunk 图；随后执行 <code>optimization</code> 的优化——tree-shaking 标记、<code>splitChunks</code> 拆包、<code>runtimeChunk</code>、<code>minimizer</code> 压缩。</li><li>输出：<code>compilation.hooks.processAssets</code> 生成最终 assets（含 <code>HtmlWebpackPlugin</code> 注入的 HTML），<code>emit</code> 钩子后由 <code>compiler.outputFileSystem</code> 写入 <code>output.path</code>；用 devServer 时文件系统是内存实现（memfs），所以 dist 目录看不到文件。</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 想看清每步耗时，用统计输出而不是猜</span>
npx webpack <span class="token parameter variable">--profile</span> <span class="token parameter variable">--json</span> <span class="token operator">&gt;</span> stats.json
npx webpack <span class="token parameter variable">--progress</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么改了 <code>src</code> 下文件 devServer 很快？答：增量编译只重建受影响的模块与 chunk，其余命中内存缓存；所以&quot;第一次慢、后面快&quot;是正常的。</li><li>陷阱：以为 loader 是在打包阶段才跑。loader 在&quot;构建模块图&quot;阶段就逐个文件执行了，<code>plugin</code> 的 <code>emit</code> 阶段拿到的是已经处理完的产物。</li><li>追问：<code>import()</code> 与 <code>import</code> 在流程上有何不同？答：静态 <code>import</code> 的模块直接进当前 chunk；<code>import()</code> 会在 chunk 图上开一个新的异步 chunk，运行时用 JSONP 动态加载，这也是 code splitting 的实现基础。</li></ul><h3 id="q7-热更新-hmr-的原理是什么-module-hot-怎么用" tabindex="-1"><a class="header-anchor" href="#q7-热更新-hmr-的原理是什么-module-hot-怎么用" aria-hidden="true">#</a> Q7 热更新（HMR）的原理是什么？<code>module.hot</code> 怎么用？</h3><p><strong>考察点</strong>：考 HMR 的完整链路（文件变更 → 编译 → WebSocket 通知 → 拉取补丁 → 模块替换），以及 accept 冒泡这个最容易答漏的点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：HMR 是&quot;改动后不刷新页面，只替换变更的模块并执行其 accept 回调&quot;的机制；它靠 devServer 的 WebSocket 通知浏览器、靠 hot-update 补丁文件同步差异，靠 <code>module.hot.accept</code> 声明更新边界。</p></blockquote><ol><li>前提：devServer 开 <code>hot: true</code>，webpack 会把 HMR runtime（<code>webpack/hot/dev-server</code> 与 <code>webpack/hot/runtime</code>）注入 bundle，并建立 WebSocket（早期用 SockJS）长连接。</li><li>文件变更：watcher 触发增量编译，产出两类补丁文件——<code>xxx.hot-update.json</code>（本次变更的 chunk 与当前 hash 清单）和 <code>xxx.hot-update.js</code>（变更模块的新代码）。</li><li>通知与拉取：devServer 通过 WebSocket 把 <code>hash</code> 推给浏览器，HMR runtime 用 JSONP 拉 <code>.hot-update.json</code>，对比本地 chunk 的 hash 决定要更新哪些 chunk，再拉对应的 <code>.hot-update.js</code>。</li><li>替换：调用 <code>hotApply</code>，把新模块写进模块缓存；然后从变更模块向上找&quot;声明了 accept 的模块&quot;，执行其回调。若整条链冒泡到入口都没人 accept，就降级为整页刷新（full reload）。</li><li><code>module.hot</code> 常用 API：<code>accept(deps, cb)</code> 声明接受自身或依赖更新、<code>dispose(cb)</code> 在旧模块被替换前清理副作用（清定时器、解绑事件）、<code>decline</code> 明确拒绝、<code>invalidate</code> 强制失效。</li><li>实际项目中不手写 <code>module.hot</code>：Vue 的 <code>vue-loader</code>、React 的 <code>react-refresh</code> 会在组件模块里自动注入 accept 与状态保留逻辑；手写只在非框架的资源（如工具模块、样式）上出现。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 手写 HMR 边界：print.js 变化时只重跑这个回调，不刷新页面</span>
<span class="token keyword">import</span> print <span class="token keyword">from</span> <span class="token string">&#39;./print.js&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>module<span class="token punctuation">.</span>hot<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  module<span class="token punctuation">.</span>hot<span class="token punctuation">.</span><span class="token function">accept</span><span class="token punctuation">(</span><span class="token string">&#39;./print.js&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;print.js 已更新&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">print</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  module<span class="token punctuation">.</span>hot<span class="token punctuation">.</span><span class="token function">dispose</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">clearInterval</span><span class="token punctuation">(</span>timer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 旧模块的清理</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么有时改了代码页面还是整页刷新？答：变更模块的父链上没人 accept，冒泡到 entry 就降级成 reload。常见于直接改 <code>main.js</code> 或改了非组件文件。</li><li>陷阱：HMR 只替换代码，<strong>不重置模块内部状态</strong>。所以 <code>const config = load()</code> 这类模块级初始化不会再跑；要重新执行必须显式 <code>module.hot.invalidate()</code> 或刷新页面。</li><li>追问：HMR 与热重载（Hot Reload）一样吗？答：不同。HMR 是模块级替换；Hot Reload 常指组件级状态保留的重载，React Refresh、Vue HMR 属于后者，是建立在 HMR 之上的能力。</li><li>陷阱：把 HMR 当性能优化手段。它是开发期工具，生产构建不会带 HMR 代码。</li></ul><h3 id="q8-tree-shaking-的原理是什么-为什么有时摇不掉" tabindex="-1"><a class="header-anchor" href="#q8-tree-shaking-的原理是什么-为什么有时摇不掉" aria-hidden="true">#</a> Q8 tree-shaking 的原理是什么？为什么有时摇不掉？</h3><p><strong>考察点</strong>：考两点——ESM 静态可分析这个前提，以及 <code>sideEffects</code> 与 <code>usedExports</code>/<code>terser</code> 的分工。答&quot;删掉没用的代码&quot;是零分答案。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：tree-shaking 依赖 ES Module 的静态结构做&quot;标记&quot;，再由 Terser 做&quot;删除&quot;；前提是 ESM、<code>mode: production</code>、以及包的 <code>sideEffects</code> 声明，任何一环缺失就摇不掉。</p></blockquote><ol><li>原理分两步：webpack 用 <code>optimization.usedExports</code>/<code>providedExports</code> 标记哪些导出被用到（标记不等于删除），最后交给 TerserPlugin 做死代码消除（Dead Code Elimination，DCE）真正删掉。</li><li>前提一：必须是 ESM。<code>import</code>/<code>export</code> 出现在模块顶层、路径是字面量，才能在不执行代码的情况下静态分析；CommonJS 的 <code>require</code> 可以写在条件里、<code>module.exports</code> 可被运行时改写，几乎无法安全删除。</li><li>前提二：<code>sideEffects</code> 字段。<code>package.json</code> 写 <code>&quot;sideEffects&quot;: false</code> 告诉打包器&quot;本包模块没有副作用，没被用到就能删&quot;；undefined 时 webpack 会保守地认为有副作用，不敢删整个模块。</li><li>有 CSS 或副作用文件时要写白名单：<code>&quot;sideEffects&quot;: [&quot;*.css&quot;, &quot;*.scss&quot;, &quot;./src/polyfill.js&quot;]</code>，否则样式被摇掉、页面莫名裸奔。</li><li>前提三：<code>mode: &#39;production&#39;</code>。开发模式下 <code>usedExports</code> 虽会标记但 Terser 不压缩，看不出效果；想调试可以临时开 <code>optimization.usedExports: true</code> 看打包注释。</li><li>常见破坏者：Babel 的 <code>@babel/preset-env</code> 若把 ESM 转成 CJS，静态结构消失（babel-loader 会自动传 <code>supportsStaticESM</code>，但单独用 <code>@babel/cli</code> 时要显式 <code>modules: false</code>）；<code>export default { a, b }</code> 这种聚合导出只能整块保留；真正有副作用的顶层语句（如 <code>window.x = 1</code>）无法被摇掉，只有看似无副作用的调用才能靠 <code>/*#__PURE__*/</code> 注解提示。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 摇不掉：整包引入 + 默认导出聚合</span>
<span class="token keyword">import</span> _ <span class="token keyword">from</span> <span class="token string">&#39;lodash&#39;</span><span class="token punctuation">;</span>                 <span class="token comment">// 全量打进产物</span>
<span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token punctuation">{</span> a<span class="token punctuation">,</span> b<span class="token punctuation">,</span> c <span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token comment">// 摇得掉：具名导入 + 纯函数标记</span>
<span class="token keyword">import</span> <span class="token punctuation">{</span> debounce <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;lodash-es&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">export</span> <span class="token keyword">const</span> add <span class="token operator">=</span> <span class="token comment">/*#__PURE__*/</span> <span class="token function">makeAdd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 提示调用无副作用</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>sideEffects: false</code> 写错了会怎样？答：真正的副作用被删，比如样式没加载、polyfill 没生效、原型扩展丢了一一这都是线上事故，只在确认&quot;每个模块纯函数式&quot;时才敢写 false。</li><li>陷阱：认为 tree-shaking 能删掉 <code>import</code> 进来但没调用的<strong>第三方 CJS 包</strong>。它只能删你项目内被证明未使用的导出，CJS 依赖基本原样打包。</li><li>追问：怎么验证摇树有没有生效？答：用 webpack-bundle-analyzer 看产物里目标模块的残留，或搜产物中是否出现该函数名字符串；也可以对比 <code>sideEffects</code> 开/关的产物体积差。</li></ul><h3 id="q9-code-splitting-怎么做-splitchunks-的策略和预加载怎么配" tabindex="-1"><a class="header-anchor" href="#q9-code-splitting-怎么做-splitchunks-的策略和预加载怎么配" aria-hidden="true">#</a> Q9 code splitting 怎么做？<code>splitChunks</code> 的策略和预加载怎么配？</h3><p><strong>考察点</strong>：考三层能力：为什么要拆、拆的三种手段（多入口 / splitChunks / 动态 import）、预加载与预取的选型。能说出 <code>chunks: &#39;async&#39;</code> 这个默认值陷阱才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：code splitting 就是把一个 bundle 拆成多个按需/并行加载的 chunk：多入口按页面拆、<code>splitChunks</code> 按复用度抽公共依赖、动态 <code>import()</code> 按路由和大组件拆；预取用 <code>webpackPrefetch</code>，预加载用 <code>webpackPreload</code>。</p></blockquote><ol><li>动态 <code>import()</code>：webpack 把 <code>import()</code> 的模块单独打成异步 chunk，运行时通过 <code>__webpack_require__.e</code> 用 JSONP 注入 <code>&lt;script&gt;</code>，返回 Promise。这是路由懒加载的实现方式。</li><li><code>splitChunks</code> 默认值：<code>chunks: &#39;async&#39;</code>（<strong>默认只拆异步 chunk</strong>）、<code>minSize: 20000</code>、<code>minChunks: 1</code>、<code>maxAsyncRequests/maxInitialRequests: 30</code>；默认有两个 cacheGroup：<code>defaultVendors</code>（<code>node_modules</code> 下、priority -10）和 <code>default</code>（被引用 ≥2 次、priority -20）。</li><li>要把同步依赖也抽出来必须写 <code>chunks: &#39;all&#39;</code>；按业务自定义 cacheGroup 时 priority 越大越优先命中，<code>reuseExistingChunk: true</code> 避免重复打包同一模块。</li><li>拆包原则：vendor 稳定（升级不频繁，便于长期缓存）、业务代码按路由切、公共组件单独成 chunk；<code>optimization.runtimeChunk: &#39;single&#39;</code> 把 webpack 运行时代码单独抽出，避免改业务代码导致 vendor 文件名变化。</li><li>预加载指令：<code>webpackPrefetch: true</code> 在浏览器空闲时以低优先级预取，用于&quot;下一步大概率会用&quot;的模块（如首页预取详情页）；<code>webpackPreload: true</code> 与父 chunk 并行加载，用于&quot;当前就一定需要&quot;的模块，滥用会抢首屏带宽。</li><li>取舍：chunk 不是越小越好。HTTP/2 有多路复用，但每个请求仍有头部与解析开销；把首屏关键路径切成十几个小 chunk 反而更慢，非关键路径才值得拆。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 路由级懒加载 + 空闲预取</span>
<span class="token keyword">const</span> routes <span class="token operator">=</span> <span class="token punctuation">[</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">path</span><span class="token operator">:</span> <span class="token string">&#39;/&#39;</span><span class="token punctuation">,</span> <span class="token function-variable function">component</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">import</span><span class="token punctuation">(</span><span class="token string">&#39;./views/Home.vue&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">path</span><span class="token operator">:</span> <span class="token string">&#39;/report&#39;</span><span class="token punctuation">,</span> <span class="token function-variable function">component</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">import</span><span class="token punctuation">(</span><span class="token comment">/* webpackChunkName: &quot;report&quot; */</span> <span class="token string">&#39;./views/Report.vue&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">path</span><span class="token operator">:</span> <span class="token string">&#39;/help&#39;</span><span class="token punctuation">,</span> <span class="token function-variable function">component</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">import</span><span class="token punctuation">(</span><span class="token comment">/* webpackPrefetch: true */</span> <span class="token string">&#39;./views/Help.vue&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token comment">// 让同步依赖也参与拆包，并把 vue 全家桶打成稳定 vendor</span>
<span class="token literal-property property">optimization</span><span class="token operator">:</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">runtimeChunk</span><span class="token operator">:</span> <span class="token string">&#39;single&#39;</span><span class="token punctuation">,</span>
  <span class="token literal-property property">splitChunks</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">chunks</span><span class="token operator">:</span> <span class="token string">&#39;all&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">cacheGroups</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token literal-property property">vendor</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">test</span><span class="token operator">:</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">[\\\\/]node_modules[\\\\/](vue|vue-router|pinia)[\\\\/]</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">,</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;vendor&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">priority</span><span class="token operator">:</span> <span class="token number">20</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
      <span class="token literal-property property">common</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">minChunks</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token literal-property property">minSize</span><span class="token operator">:</span> <span class="token number">20000</span><span class="token punctuation">,</span> <span class="token literal-property property">priority</span><span class="token operator">:</span> <span class="token operator">-</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token literal-property property">reuseExistingChunk</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>陷阱：只写 <code>splitChunks: { cacheGroups: {...} }</code> 却没写 <code>chunks: &#39;all&#39;</code>，结果 vendor 死活不生效——因为默认只管异步 chunk，而入口是同步的。</li><li>追问：<code>preload</code> 与 <code>prefetch</code> 有什么区别？答：<code>preload</code> 与父 chunk 并行、优先级高、浏览器必须下载；<code>prefetch</code> 空闲时下载、优先级最低，且父 chunk 加载完才触发。用错会把&quot;将来要用的&quot;塞进首屏关键路径。</li><li>追问：拆完后 chunk 数量暴涨怎么排查？答：看分析图里是否有大量 1-2KB 的小 chunk，通常是 <code>minSize</code> 太小或 <code>maxInitialRequests</code> 放太宽，把它们合并回主 chunk 或提高 <code>minSize</code>。</li></ul><h3 id="q10-source-map-有哪几种-生产环境到底该不该开" tabindex="-1"><a class="header-anchor" href="#q10-source-map-有哪几种-生产环境到底该不该开" aria-hidden="true">#</a> Q10 source map 有哪几种？生产环境到底该不该开？</h3><p><strong>考察点</strong>：考 <code>devtool</code> 修饰词（eval/cheap/module/inline/hidden/nosources）的真实含义，以及生产环境&quot;要不要、怎么给、给谁&quot;的工程判断。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>devtool</code> 的取值是&quot;如何生成映射&quot;的开关组合，开发用 <code>eval-cheap-module-source-map</code> 求快，生产默认关闭，需要线上排错时用 <code>hidden-source-map</code> 生成但不上传到 CDN、只传给错误监控平台。</p></blockquote><ol><li>基础形式：<code>source-map</code> 生成独立 <code>.map</code> 文件并在产物末尾加 <code>//# sourceMappingURL=</code> 注释；<code>inline-source-map</code> 把 map 以 DataURL 内联进产物（体积膨胀，只适合开发）。</li><li><code>eval</code> 前缀：用 <code>eval()</code> 包裹每个模块执行，映射快但映射到的是转换后的中间代码；因为用 eval，开启 CSP <code>unsafe-eval</code> 限制的页面会失效。</li><li><code>cheap</code> 前缀：只映射到行、不映射到列，构建速度快很多；<code>module</code> 前缀：映射到 loader 转换<strong>之前</strong>的源码（也就是你写的 TS/Vue 源码），不加 module 会指向 babel 的输出。</li><li><code>hidden-source-map</code>：正常生成 <code>.map</code> 文件，但<strong>不在产物里写注释</strong>，浏览器开发者工具不会自动加载；错误监控 SDK 配置 <code>sourceMappingURL</code> 后可以自行还原堆栈。</li><li><code>nosources-source-map</code>：有映射但不带源码内容，能看到行列和文件名，看不到源码原文，是&quot;能定位但不泄露源码&quot;的折中。</li><li>生产推荐：常规项目 <code>devtool: false</code>；接入 Sentry 等监控时用 <code>hidden-source-map</code>，并在构建后把 <code>.map</code> 上传到监控平台，同时确保 <code>.map</code> 不出现在最终发布的 CDN 上（要么不上传，要么加访问控制）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// webpack.config.js</span>
module<span class="token punctuation">.</span><span class="token function-variable function">exports</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">env</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span>
  <span class="token literal-property property">devtool</span><span class="token operator">:</span> env<span class="token punctuation">.</span>production <span class="token operator">?</span> <span class="token string">&#39;hidden-source-map&#39;</span> <span class="token operator">:</span> <span class="token string">&#39;eval-cheap-module-source-map&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// vite.config.js：Vite 生产默认 false，这里按需开启隐藏映射</span>
<span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token punctuation">{</span> <span class="token literal-property property">build</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">sourcemap</span><span class="token operator">:</span> <span class="token string">&#39;hidden&#39;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么生产用 <code>hidden-source-map</code> 而不是 <code>source-map</code>？答：<code>source-map</code> 会在产物末尾留注释，任何人打开控制台都能拿到完整源码，等同于源码泄露；<code>hidden</code> 去掉注释，只有拿到 map 文件的人才能还原。</li><li>陷阱：开发用 <code>source-map</code>（不 eval、不 cheap）。构建慢、映射准，改一次等好几秒，属于用错档位。</li><li>追问：source map 会影响线上性能吗？答：浏览器只在开发者工具打开时才解析 map，运行时不加载，所以不影响首屏；但 <code>eval</code> 类 devtool 会改变产物形态，绝不能上生产。</li></ul><h3 id="q11-构建速度太慢-你怎么优化" tabindex="-1"><a class="header-anchor" href="#q11-构建速度太慢-你怎么优化" aria-hidden="true">#</a> Q11 构建速度太慢，你怎么优化？</h3><p><strong>考察点</strong>：考是否有&quot;先量化再优化&quot;的方法论，以及缓存、并行、缩小范围三类手段的具体配置。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：先量化定位——用 profile 与 speed-measure-webpack-plugin 找出耗时大头，再按&quot;缩小搜索与处理范围 → 开缓存 → 上并行/换快编译器 → 减少工作量&quot;的顺序优化。</p></blockquote><ol><li>量化：<code>webpack --profile --json &gt; stats.json</code> 看各模块与 loader 耗时，或 <code>speed-measure-webpack-plugin</code> 直接输出每个 loader/plugin 的耗时；不要凭感觉换工具。</li><li>缩小范围：<code>resolve.extensions</code> 只留必要的后缀、<code>alias</code> 配绝对路径、<code>module.rules</code> 精确 <code>include: src</code>、<code>resolve.modules</code> 限定 <code>node_modules</code> 位置、<code>resolve.symlinks: false</code>（pnpm/monorepo 场景省去真实路径解析）。</li><li>开缓存：webpack 5 写 <code>cache: { type: &#39;filesystem&#39;, buildDependencies: { config: [__filename] } }</code>；<code>babel-loader</code> 加 <code>cacheDirectory: true</code>；Terser 的 <code>cache</code> 默认在持久化缓存里；CI 上把缓存目录做 key 缓存复用。</li><li>上并行：<code>thread-loader</code> 放在耗时 loader 之前把工作分给 worker 池（本身有启动开销，只对重 loader 值得）；<code>terser-webpack-plugin</code> 的 <code>parallel</code> 默认已是 CPU 数减一。</li><li>换快编译器：用 <code>esbuild-loader</code>/<code>swc-loader</code> 替代 <code>babel-loader</code>，压缩交给 <code>esbuild</code> 或 <code>TerserPlugin</code> 的 esbuild minify，通常能省掉一半以上的构建时间。</li><li>减少工作量：TypeScript 用 <code>transpileOnly</code>/<code>isolatedModules</code> 只转不检查，类型检查交给 <code>fork-ts-checker-webpack-plugin</code> 或在 CI 单独跑 <code>tsc --noEmit</code>；<code>externals</code> + CDN 外置大库；<code>IgnorePlugin</code> 砍掉 moment 的 locale 等无用文件；库加 <code>sideEffects</code> 让摇树更彻底。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">cache</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;filesystem&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">buildDependencies</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">config</span><span class="token operator">:</span> <span class="token punctuation">[</span>__filename<span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">resolve</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">extensions</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;.ts&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;.tsx&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;.js&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token literal-property property">symlinks</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">module</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">rules</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span>
      <span class="token literal-property property">test</span><span class="token operator">:</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">\\.[jt]sx?$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">,</span> <span class="token literal-property property">include</span><span class="token operator">:</span> path<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>__dirname<span class="token punctuation">,</span> <span class="token string">&#39;src&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
      <span class="token literal-property property">use</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token literal-property property">loader</span><span class="token operator">:</span> <span class="token string">&#39;esbuild-loader&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">options</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">target</span><span class="token operator">:</span> <span class="token string">&#39;es2015&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">tsconfigRaw</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">optimization</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">minimizer</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token keyword">new</span> <span class="token class-name">TerserPlugin</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">parallel</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token literal-property property">cache</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：持久化缓存什么时候失效？答：配置文件、loader 代码、依赖版本、<code>NODE_ENV</code> 变化都会让缓存整体失效；改了自定义 loader 要让 <code>buildDependencies</code> 带上它，否则用到旧缓存结果。</li><li>陷阱：无脑上 thread-loader。它对小项目是负优化（worker 启动与序列化开销大于收益），只应加在最耗时的 loader 前面。</li><li>追问：升级 webpack 5 就能快吗？答：持久化缓存和更好的默认值确实能显著提速，但真正的大头通常还是 Babel 编译与 Terser 压缩，换 esbuild/swc 收益更大。</li></ul><h3 id="q12-产物太大-你怎么定位问题并优化" tabindex="-1"><a class="header-anchor" href="#q12-产物太大-你怎么定位问题并优化" aria-hidden="true">#</a> Q12 产物太大，你怎么定位问题并优化？</h3><p><strong>考察点</strong>：考分析工具的使用与常见&quot;体积元凶&quot;的清单，要能给出查证步骤而不是空谈&quot;用 CDN&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：先用 webpack-bundle-analyzer 看产物构成找出占比最大的模块，再按&quot;重复打包 → 全量引入 → 未摇树 → 未拆包 → 未压缩&quot;的顺序逐项排掉。</p></blockquote><ol><li>工具：<code>webpack-bundle-analyzer</code> 的 <code>BundleAnalyzerPlugin</code> 生成可交互的矩形树图（treemap），能按 gzip 后体积排序；<code>webpack --profile --json &gt; stats.json</code> 可上传到在线分析站点；Vite 用 <code>rollup-plugin-visualizer</code>。</li><li>更准的视角用 <code>source-map-explorer</code>：它基于 source map 归因到<strong>源码文件</strong>而不是 chunk，能发现&quot;某依赖被多个 chunk 重复打入&quot;。</li><li>元凶一：重复依赖。同一库的多个版本共存（<code>npm ls lodash</code>/<code>pnpm why</code> 可查），用 <code>overrides</code>/<code>resolutions</code>/<code>pnpm.overrides</code> 统一版本。</li><li>元凶二：全量引入。<code>import _ from &#39;lodash&#39;</code> 换 <code>lodash-es</code> + 具名导入，<code>echarts</code> 用按需引入，UI 库确认按需插件生效（<code>babel-plugin-import</code>/<code>unplugin-vue-components</code>），<code>moment</code> 换 <code>dayjs</code> 或用 <code>IgnorePlugin</code> 去掉 locale。</li><li>元凶三：没摇树/没压缩。检查依赖是否提供 ESM 入口（<code>mainFields</code> 里 <code>module</code> 要优先）、<code>sideEffects</code> 是否声明；确认产物是 gzip/brotli 后的体积（<code>compression-webpack-plugin</code>），别被未压缩数字吓到。</li><li>元凶四：没拆包或拆得不对。首屏 chunk 过大时做路由级懒加载，把报表、编辑器、富文本这类重模块挪出关键路径；也可考虑 <code>externals</code> 外置到 CDN、或先做低垂果实（如删掉只用于开发的 polyfill）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// webpack.config.js</span>
<span class="token keyword">const</span> <span class="token punctuation">{</span> BundleAnalyzerPlugin <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;webpack-bundle-analyzer&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">plugins</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token keyword">new</span> <span class="token class-name">BundleAnalyzerPlugin</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">analyzerMode</span><span class="token operator">:</span> <span class="token string">&#39;static&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">openAnalyzer</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span>
    <span class="token literal-property property">reportFilename</span><span class="token operator">:</span> <span class="token string">&#39;report.html&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">gzipSize</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：首屏加载慢，但产物总体积不大，怎么想？答：看首屏关键路径的 chunk 与资源瀑布图，可能是拆包把首屏依赖切碎了、或者某个大库被同步引入主 chunk，用分析图的 initial chunk 视角找。</li><li>陷阱：只看未压缩体积。一个 1MB 的 JS 压缩后可能只有 250KB，判断优先级必须用 gzip/brotli 后的体积排序。</li><li>追问：CDN 外置（<code>externals</code>）是万能方案吗？答：不是。它把下载成本转给第三方域名与用户的额外连接，且失去版本一致性保障；只有在库体积大、版本稳定、且有可用公共 CDN 时才划算。</li></ul><h3 id="q13-vite-为什么快-说说它的原理" tabindex="-1"><a class="header-anchor" href="#q13-vite-为什么快-说说它的原理" aria-hidden="true">#</a> Q13 Vite 为什么快？说说它的原理</h3><p><strong>考察点</strong>：考是否理解&quot;开发不打包、生产才打包&quot;这个核心，以及依赖预构建、原生 ESM、基于 ESM 的 HMR 三块拼图。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Vite 开发期利用浏览器原生 ES Module 做按需编译，不打包整个应用，因此冷启动时间与项目规模基本无关；生产期则用 Rollup 打包，兼顾产物质量。</p></blockquote><ol><li>开发服务器（serve）：浏览器请求 <code>main.js</code> 时，Vite 才把这个模块（以及它 import 的下一个模块）编译成浏览器能执行的 ESM 返回，请求驱动、按需编译；不再像 webpack 那样先构建完整依赖图。</li><li>依赖预构建（Dependency Pre-Bundling）：用 esbuild 把 <code>node_modules</code> 里的 CommonJS/UMD 依赖转成 ESM，并把内部模块成百上千的包（如 <code>lodash-es</code>）合并成单个文件，避免&quot;一个依赖引发几百个 HTTP 请求&quot;。结果缓存在 <code>node_modules/.vite</code>，锁文件或配置变化时重建。</li><li>HMR：基于原生 ESM 的边界替换。文件变更后服务端通过 WebSocket 通知浏览器，只让变更模块自身或其 importer 重新请求，不需要重建整张模块图，因此大项目里热更新也很快。</li><li>内置转换：<code>.ts</code>、<code>.vue</code>、<code>.scss</code>、JSX 都由 Vite 直接处理，esbuild 负责 TS/JSX 转译（<strong>只转译不检查类型</strong>），类型检查仍需 <code>vue-tsc</code>/<code>tsc --noEmit</code>。</li><li>生产构建（build）：用 Rollup 打包，默认 <code>build.target</code> 为 <code>&#39;modules&#39;</code>（面向支持原生 ESM 的浏览器，Vite 6 起改为 <code>&#39;baseline-widely-available&#39;</code>），做 tree-shaking、CSS 抽取、资源指纹；需要兼容旧浏览器时加 <code>@vitejs/plugin-legacy</code> 生成 legacy 包与 polyfill。</li><li>插件体系：兼容大部分 Rollup 插件，另加 Vite 独有钩子（<code>config</code>、<code>configureServer</code>、<code>transformIndexHtml</code>、<code>handleHotUpdate</code>）；插件可用 <code>apply: &#39;serve&#39; | &#39;build&#39;</code> 限定生效环境。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// vite.config.js</span>
<span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token function">defineConfig</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
  <span class="token literal-property property">plugins</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token function">vue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token literal-property property">server</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">port</span><span class="token operator">:</span> <span class="token number">5173</span><span class="token punctuation">,</span> <span class="token literal-property property">warmup</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">clientFiles</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;./src/main.js&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">optimizeDeps</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">include</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;lodash-es&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token comment">// 手动指定需预构建的依赖</span>
  <span class="token literal-property property">build</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">target</span><span class="token operator">:</span> <span class="token string">&#39;modules&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">rollupOptions</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">output</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">manualChunks</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">vendor</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;vue&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 Vite 开发快、生产构建有时反而比 webpack 慢？答：生产构建由 Rollup 完成，Rollup 主体是 JS 单线程，超大项目上打包仍是瓶颈（Rolldown 等 Rust 实现正在解决）；&quot;dev 快&quot;不等于&quot;build 快&quot;。</li><li>陷阱：以为预构建只是转格式。它同时做了 CJS→ESM 转换、请求合并、以及内部依赖的缓存，这三件事共同决定了首次打开页面的速度。</li><li>追问：为什么 Vite 要求浏览器支持原生 ESM？答：它的开发服务器直接给浏览器喂 ESM，不支持 <code>type=&quot;module&quot;</code> 的老浏览器在开发期就跑不起来，所以 Vite 明确不支持 IE11（生产兼容靠 <code>plugin-legacy</code> 也有上限）。</li></ul><h3 id="q14-vite-和-webpack-怎么选-各自强在哪" tabindex="-1"><a class="header-anchor" href="#q14-vite-和-webpack-怎么选-各自强在哪" aria-hidden="true">#</a> Q14 Vite 和 Webpack 怎么选？各自强在哪？</h3><p><strong>考察点</strong>：考选型判断力，而不是背参数。要能说清开发/生产差异、生态差异、以及老项目为什么通常不动。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：新项目、现代浏览器、Vue3/React 技术栈优先 Vite（开发体验碾压、配置少）；老项目、需要深度定制构建流程、依赖 webpack 特有 loader/插件或模块联邦的场景继续用 Webpack。</p></blockquote><ol><li>原理差异：Webpack 是&quot;先打包再服务&quot;，dev 启动要构建完整依赖图，规模越大越慢；Vite 的 dev 是按需编译加原生 ESM，启动近乎常数时间。</li><li>生产差异：Webpack 自带完整优化体系（splitChunks、Module Federation 等，可调项极多）；Vite 生产交给 Rollup，产物干净、tree-shaking 彻底，但复杂分包的可控性不如 webpack。</li><li>生态差异：Webpack 的 loader/plugin 最庞大，冷门资源格式与公司内部历史插件都集中在它身上；Vite 插件较新，遇到偏门需求可能得自己写 Rollup 插件。</li><li>一致性差异：Vite 的 dev（esbuild）与 build（Rollup）是两套管线，偶发行为不一致（如 CJS 依赖 dev 能预构建、build 需额外配置）；Webpack 两端共用同一套 loader/plugin。</li><li>成本差异：新项目用 Vite 配置量通常只有 webpack 的十分之一；迁移存量项目则要逐个处理别名、环境变量、自定义 loader 与 CSS 处理顺序的差异。</li><li>结论：新项目优先 Vite；存量项目除非构建慢到影响开发效率，否则不动——迁移收益比不上回归风险。</li></ol><table><thead><tr><th>维度</th><th>Webpack</th><th>Vite</th></tr></thead><tbody><tr><td>dev 原理</td><td>先打包，再服务内存产物</td><td>原生 ESM，按需编译</td></tr><tr><td>冷启动</td><td>随项目规模增长</td><td>基本与规模无关</td></tr><tr><td>生产打包</td><td>Webpack 自身</td><td>Rollup</td></tr><tr><td>配置复杂度</td><td>高，可调性强</td><td>低，约定优先</td></tr><tr><td>插件生态</td><td>极大，历史包袱也大</td><td>较新，兼容 Rollup 插件</td></tr><tr><td>模块联邦</td><td>原生支持</td><td>需实验插件</td></tr></tbody></table><p><strong>追问与易错点</strong>：</p><ul><li>追问：把 webpack 项目迁到 Vite 最容易出问题的地方？答：<code>process.env</code> 要换成 <code>import.meta.env</code>、别名与 <code>base</code> 要重新配、Node 内置模块的 polyfill 默认不提供、以及依赖 CJS 的包需要 <code>optimizeDeps.include</code>。</li><li>陷阱：说&quot;Vite 就是不要打包&quot;。生产必须打包（Rollup），只是开发期不打包；如果生产也不打包，就会产生成百上千个请求与无 tree-shaking 的产物。</li><li>追问：什么情况下必须留在 Webpack？答：需要 Module Federation 做微前端、需要兼容 IE11、有大量自研 webpack loader/plugin、或构建流程被 CI/发布系统深度耦合时。</li></ul><h3 id="q15-vite-的环境变量和多环境配置怎么做" tabindex="-1"><a class="header-anchor" href="#q15-vite-的环境变量和多环境配置怎么做" aria-hidden="true">#</a> Q15 Vite 的环境变量和多环境配置怎么做？</h3><p><strong>考察点</strong>：考 <code>.env</code> 文件加载优先级、<code>VITE_</code> 前缀这条安全护栏，以及&quot;构建时替换&quot;带来的产物复用问题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Vite 用 <code>.env</code>/<code>.env.[mode]</code> 文件加载环境变量，只有 <code>VITE_</code> 前缀的会通过 <code>import.meta.env</code> 暴露给客户端；它是构建时静态替换，因此一份产物只能对应一个环境。</p></blockquote><ol><li>文件与优先级：<code>.env</code>（所有模式）→ <code>.env.local</code>（所有模式，应加入 .gitignore）→ <code>.env.[mode]</code> → <code>.env.[mode].local</code>；同名变量后加载的覆盖先加载的。</li><li>模式（mode）：<code>vite dev</code> 默认 <code>development</code>，<code>vite build</code> 默认 <code>production</code>；用 <code>vite build --mode staging</code> 加载 <code>.env.staging</code>，并可通过 <code>import.meta.env.MODE</code> 读到。</li><li>前缀护栏：只有 <code>VITE_</code> 开头的变量会被注入客户端（可用 <code>envPrefix</code> 改前缀）。这是防止把数据库密码、内部 token 这类服务端变量误打进前端产物的关键机制，<code>import.meta.env</code> 里绝不会出现未加前缀的变量。</li><li>内置变量：<code>import.meta.env.MODE</code>、<code>BASE_URL</code>、<code>DEV</code>、<code>PROD</code>、<code>SSR</code>；TypeScript 项目要加 <code>/// &lt;reference types=&quot;vite/client&quot; /&gt;</code> 并声明 <code>ImportMetaEnv</code> 才有提示。</li><li>实现机制：变量在构建时被<strong>静态文本替换</strong>成字面量（等价于 webpack 的 DefinePlugin），所以 <code>import.meta.env[key]</code> 这种动态取值不生效，必须写 <code>import.meta.env.VITE_API_BASE</code>。</li><li>想一份产物跑多环境：不要靠环境变量，改用运行时配置——<code>public/config.js</code> 里挂 <code>window.__APP_CONFIG__</code> 并在 <code>index.html</code> 里先引入，或启动时 <code>fetch(&#39;/config.json&#39;)</code>；部署时只替换这一个文件，不用重新构建。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// .env.production</span>
<span class="token constant">VITE_API_BASE</span><span class="token operator">=</span>https<span class="token operator">:</span><span class="token operator">/</span><span class="token operator">/</span>api<span class="token punctuation">.</span>example<span class="token punctuation">.</span>com
<span class="token constant">DB_PASSWORD</span><span class="token operator">=</span>xxx            <span class="token comment">// 没有 VITE_ 前缀，不会进产物</span>

<span class="token comment">// src/api/http.js</span>
<span class="token keyword">const</span> base <span class="token operator">=</span> <span class="token keyword">import</span><span class="token punctuation">.</span>meta<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">VITE_API_BASE</span><span class="token punctuation">;</span> <span class="token comment">// 构建时被替换为字符串字面量</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">import</span><span class="token punctuation">.</span>meta<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">MODE</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// &quot;production&quot;</span>

<span class="token comment">// public/config.js —— 运行时注入，部署时可改</span>
window<span class="token punctuation">.</span>__APP_CONFIG__ <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">apiBase</span><span class="token operator">:</span> <span class="token string">&#39;https://api.example.com&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>陷阱：把密钥写成 <code>VITE_DB_PASSWORD</code>。加了前缀就会被原样打进 JS，任何人按 F12 都能看到——前缀是&quot;可以公开&quot;的标记，不是加密。</li><li>追问：为什么改了 <code>.env</code> 要重启 dev server？答：变量在启动与构建时被替换并参与依赖预构建的哈希，改文件后需要重启（或 Vite 自动重启）才能生效。</li><li>追问：webpack 里怎么对应？答：用 <code>new webpack.DefinePlugin({ &#39;process.env.API_BASE&#39;: JSON.stringify(url) })</code>，注意值必须 <code>JSON.stringify</code>，否则字符串会被当成变量名解析成报错代码。</li></ul><h3 id="q16-babel-的原理是什么-preset-和-plugin-的执行顺序呢" tabindex="-1"><a class="header-anchor" href="#q16-babel-的原理是什么-preset-和-plugin-的执行顺序呢" aria-hidden="true">#</a> Q16 Babel 的原理是什么？<code>preset</code> 和 <code>plugin</code> 的执行顺序呢？</h3><p><strong>考察点</strong>：考 Babel 三步流程（解析→转换→生成）、它是&quot;源码到源码的转译器而不是打包器&quot;这个定位，以及顺序规则这个高频细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Babel 是源码到源码的转译器，流程是解析成 AST、由插件通过 visitor 改写 AST、再生成代码与 source map；plugin 按数组正序执行，preset 按数组倒序执行，且 plugin 先于 preset。</p></blockquote><ol><li>解析（parse）：<code>@babel/parser</code> 把源码转成抽象语法树（Abstract Syntax Tree，AST），遵循 ESTree 规范；语法插件（<code>@babel/plugin-syntax-*</code>）只负责让解析器认识新语法，不做转换。</li><li>转换（transform）：<code>@babel/traverse</code> 深度优先遍历 AST，插件通过 <code>visitor</code> 声明&quot;遇到某类节点时做什么&quot;，用 <code>@babel/types</code> 增删改节点。AST 只描述结构，注释与格式信息默认不保留。</li><li>生成（generate）：<code>@babel/generator</code> 把 AST 打印回代码，同时产出 source map（映射回原始源码），再配合 <code>@babel/code-frame</code> 给出可读的报错位置。</li><li>执行顺序：<code>plugins: [A, B]</code> 按 A 再到 B 执行；<code>presets: [X, Y]</code> 按 Y 再到 X 执行（倒序）。整体上同一节点先被所有 plugin 处理，再被 preset 处理，所以顺序写反会导致语法还没降级就去做别的处理。</li><li>preset 的本质是&quot;插件的集合加顺序&quot;：<code>@babel/preset-env</code> 根据 <code>targets</code>（来自 browserslist）自动挑选需要的转换插件，内部大致按&quot;从新语法到旧语法&quot;排列，保证高版本语法优先降级。</li><li>配置文件的层级：<code>babel.config.js</code> 作用于整个项目（monorepo 推荐），<code>.babelrc</code>/<code>.babelrc.js</code> 只作用于所在包目录；两者同时存在时按&quot;根配置 → 就近配置&quot;合并，<code>overrides</code>/<code>env</code> 可以按环境细分。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 手写一个 Babel 插件：删掉所有 console.log 调用</span>
module<span class="token punctuation">.</span><span class="token function-variable function">exports</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token function">dropConsole</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;drop-console&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">visitor</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token function">CallExpression</span><span class="token punctuation">(</span><span class="token parameter">path</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>path<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;callee&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">matchesPattern</span><span class="token punctuation">(</span><span class="token string">&#39;console.log&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> path<span class="token punctuation">.</span><span class="token function">remove</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// babel.config.js</span>
module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">presets</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">[</span><span class="token string">&#39;@babel/preset-env&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">targets</span><span class="token operator">:</span> <span class="token string">&#39;&gt; 0.5%, last 2 versions, not dead&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">modules</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token literal-property property">plugins</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;@babel/plugin-transform-runtime&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;./plugins/drop-console&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 Babel 转完代码体积反而变大？答：helper 函数会被内联到每个文件（如 <code>_classCallCheck</code>），用 <code>@babel/plugin-transform-runtime</code> 改成从 <code>@babel/runtime</code> 引入就能复用，代价是运行时多一个依赖。</li><li>陷阱：把 Babel 当构建工具。它不解析 <code>import</code> 的依赖关系、不打包、不做 tree-shaking，这些是 webpack/Rollup/Vite 的职责。</li><li>追问：<code>modules: false</code> 是什么意思？答：让 preset-env 不要把我写的 ESM 转成 CommonJS，保留 <code>import</code>/<code>export</code> 交给打包器做 tree-shaking。babel-loader 会自动传 <code>supportsStaticESM</code> 达到同样效果。</li></ul><h3 id="q17-polyfill-怎么配-browserslist、usebuiltins、core-js-之间是什么关系" tabindex="-1"><a class="header-anchor" href="#q17-polyfill-怎么配-browserslist、usebuiltins、core-js-之间是什么关系" aria-hidden="true">#</a> Q17 polyfill 怎么配？browserslist、<code>useBuiltIns</code>、core-js 之间是什么关系？</h3><p><strong>考察点</strong>：考 polyfill 策略的完整链路：browserslist 决定目标环境，preset-env 决定要不要转语法，core-js 决定要补哪些 API。这是答错率极高的一题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Babel 只降级<strong>语法</strong>，新 API 必须靠 core-js 提供；browserslist 声明目标浏览器，<code>useBuiltIns: &#39;usage&#39;</code> 让 preset-env 按实际用到的 API 从 core-js 按需注入，async/await 降级后的 generator 运行时由 regenerator 提供。</p></blockquote><ol><li>分清两件事：<code>const fn = () =&gt; {}</code>、可选链属于<strong>语法</strong>，Babel 转成 ES5 即可；<code>Promise</code>、<code>Array.prototype.flat</code>、<code>URLSearchParams</code> 属于<strong>运行时 API</strong>，旧浏览器里根本不存在，转语法无用，必须注入实现。</li><li>browserslist：写在 <code>package.json</code> 的 <code>browserslist</code> 字段或 <code>.browserslistrc</code> 里，例如 <code>&gt; 0.5%, last 2 versions, not dead</code>（<code>defaults</code> 等价于此再加 Firefox ESR）；Babel、autoprefixer、esbuild、swc 都读同一份配置，改一处全局生效。可用 <code>npx browserslist</code> 查看解析结果。</li><li>core-js：API polyfill 的实现库（core-js/stable 是全量）。<code>useBuiltIns</code> 三个档位：<code>false</code>（默认，不自动注入）、<code>&#39;entry&#39;</code>（在 <code>import &#39;core-js&#39;</code> 处按 targets 替换成所需的具体模块）、<code>&#39;usage&#39;</code>（推荐，扫描代码里用到的 API 按文件按需注入），后两档都要写 <code>corejs: { version: &#39;3.x&#39; }</code> 并安装对应版本。</li><li>regenerator：Babel 把 <code>async/await</code> 降级成 generator + 状态机后，需要 regenerator 运行时来执行；默认 helper 内联进产物，用 <code>@babel/plugin-transform-runtime</code> 可改为从 <code>@babel/runtime</code> 引入，避免每个文件重复内联。</li><li><code>&#39;usage&#39;</code> 的盲点：它靠静态分析识别 API 用法，对动态访问（<code>arr[methodName]()</code>、字符串拼出来的属性）识别不到，也可能把不需要的补进来；第三方依赖默认不处理（在 <code>node_modules</code> 里被排除），所以库自身要做好兼容或用 <code>transpileDependencies</code> 放行。</li><li>取舍：polyfill 是有体积代价的。目标是&quot;明确支持的浏览器下限 + 按需注入&quot;，而不是无脑全量；如果产品可以放弃老浏览器，把 browserslist 调高一位往往比任何 polyfill 优化都省体积。现代替代方案是 Vite 的 <code>@vitejs/plugin-legacy</code>，为旧浏览器单独产出 legacy chunk 与 polyfill，新浏览器不付代价。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// babel.config.js</span>
module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">presets</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">[</span><span class="token string">&#39;@babel/preset-env&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">targets</span><span class="token operator">:</span> <span class="token string">&#39;&gt; 0.5%, last 2 versions, not dead&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">useBuiltIns</span><span class="token operator">:</span> <span class="token string">&#39;usage&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">corejs</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">version</span><span class="token operator">:</span> <span class="token string">&#39;3.37&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">proposals</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token literal-property property">modules</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>陷阱：以为配了 <code>@babel/preset-env</code> 老浏览器就能跑。<code>Promise</code> 缺失照样白屏报错——语法降级和 API 补齐是两件事，必须回答出 core-js。</li><li>追问：<code>useBuiltIns: &#39;usage&#39;</code> 和 <code>@babel/plugin-transform-runtime</code> 的 <code>corejs</code> 选项能一起用吗？答：不要混用。前者注入全局 polyfill（污染全局），后者注入沙箱化的局部实现；同时开会导致重复引入与体积翻倍，做业务应用选 <code>usage</code>，做第三方库选 runtime。</li><li>追问：<code>core-js</code> 装成 2 还是 3？答：必须 core-js@3，core-js@2 已不再维护，且 <code>useBuiltIns</code> 与 <code>corejs</code> 版本号必须与安装的包一致，否则构建直接报错。</li></ul><h3 id="q18-rollup-有什么特点-什么场景适合用它" tabindex="-1"><a class="header-anchor" href="#q18-rollup-有什么特点-什么场景适合用它" aria-hidden="true">#</a> Q18 Rollup 有什么特点？什么场景适合用它？</h3><p><strong>考察点</strong>：考&quot;库打包器&quot;的定位与产物特征，要能说清它和 webpack 的分工，而不是罗列插件名。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Rollup 是面向 ES Module 的打包器，擅长把库打成干净、无运行时包装的多格式产物（esm/cjs/umd），适合组件库、工具库和 Vite 的生产构建；不适合做带 HMR、复杂分包的应用开发服务器。</p></blockquote><ol><li>核心优势：基于 ESM 静态分析做 tree-shaking，产物没有 webpack 的 <code>__webpack_require__</code> 运行时代码与模块包装，代码更接近手写，体积更小、可读性更好。</li><li>输出格式：一次构建可同时产出 <code>esm</code>（给打包器消费，保留 tree-shaking 能力）、<code>cjs</code>（给 Node/老工具链）、<code>umd</code>/<code>iife</code>（给 <code>&lt;script&gt;</code> 直接引用的场景），并在 <code>package.json</code> 用 <code>module</code>/<code>main</code>/<code>exports</code> 字段分别指向。</li><li>插件机制：钩子分 build 阶段（<code>options</code>/<code>resolveId</code>/<code>load</code>/<code>transform</code>）与 output 阶段（<code>renderChunk</code>/<code>generateBundle</code>），API 简洁，插件只处理自己关心的资源类型。</li><li>生态短板：默认只认 JS/ESM，CJS 依赖要 <code>@rollup/plugin-commonjs</code>，Node 内置模块要 <code>@rollup/plugin-node-resolve</code> 与 <code>builtins</code>；代码分割、HMR、dev server 都不是它的强项，需要额外插件或交给 Vite。</li><li>典型用法：组件库/工具库发布，配 <code>rollup-plugin-dts</code> 或 <code>tsc --emitDeclarationOnly</code> 产出类型声明；Vite 的生产构建内部就是 Rollup，所以 Vite 项目的 <code>build.rollupOptions</code> 里写的其实就是 Rollup 配置。</li><li>与 webpack 的分工一句话：<strong>做应用用 Webpack/Vite，做库用 Rollup</strong>；选型看的是&quot;产物给谁用&quot;，应用产物给浏览器和 CDN，库产物要给别的构建工具继续消费。</li></ol><table><thead><tr><th>维度</th><th>Rollup</th><th>Webpack</th></tr></thead><tbody><tr><td>定位</td><td>库/包打包</td><td>应用构建器</td></tr><tr><td>产物形态</td><td>干净，无运行时包装</td><td>带 runtime 与模块包装</td></tr><tr><td>tree-shaking</td><td>更强（纯 ESM 语义）</td><td>强，但受 CJS 与 loader 影响</td></tr><tr><td>代码分割/HMR</td><td>需插件或交给 Vite</td><td>原生支持</td></tr><tr><td>多资源类型</td><td>全靠插件</td><td>loader 生态庞大</td></tr></tbody></table><p><strong>追问与易错点</strong>：</p><ul><li>追问：库产物为什么要同时出 ESM 和 CJS？答：ESM 让使用方的打包器能继续 tree-shaking（<code>sideEffects: false</code> 配合），CJS 兼容仍在用 <code>require</code> 的老环境（Node 老版本、Jest 默认配置、老构建工具）。</li><li>陷阱：以为 Rollup 组件的产物一定比 webpack 小。不做 <code>sideEffects</code> 声明、不做 <code>external</code>（把 vue/react 打进去）时，体积同样会失控。</li><li>追问：<code>external</code> 为什么对库特别重要？答：库不应把宿主已安装的依赖（如 vue、react）打进来，否则使用方会出现双实例，React hooks 报错、Vue 响应式失效都是这么来的。</li></ul><h3 id="q19-esbuild-和-swc-为什么比-babel-快那么多" tabindex="-1"><a class="header-anchor" href="#q19-esbuild-和-swc-为什么比-babel-快那么多" aria-hidden="true">#</a> Q19 esbuild 和 swc 为什么比 Babel 快那么多？</h3><p><strong>考察点</strong>：考是否理解&quot;语言与架构&quot;层面的原因，而不是只答&quot;因为用 Go/Rust 写的&quot;。要能说出它们放弃了什么。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：esbuild（Go）和 swc（Rust）用原生语言编译成机器码、多线程并行处理，且从架构上避免了 JS 工具链的解析/序列化开销；代价是插件生态与语法覆盖不如 Babel，且它们不做类型检查。</p></blockquote><ol><li>语言与执行方式：Babel/Terser 跑在 Node 上是单线程 JS，受解释执行、GC 与对象分配开销限制；esbuild/swc 是原生二进制，无启动期 JIT 预热，可直接吃满多核。</li><li>架构差异：esbuild 整个流程在同一个进程内共享数据结构，避免了&quot;插件之间反复传字符串/AST&quot;的序列化复制；解析器与打印器都是自研的，且一次遍历同时完成多项工作。</li><li>减少不必要的工作：esbuild 不解析 TypeScript 的类型（把类型当注释跳过）、不做跨文件的类型检查、不做复杂的 AST 兼容层，因此单文件转译极快。</li><li>能力边界：esbuild 不做类型检查（要检查得单独跑 <code>tsc --noEmit</code>），不注入 polyfill（<code>target</code> 只决定语法降级，新 API 仍要 core-js 或 <code>@vitejs/plugin-legacy</code>），也不支持完整 Babel 插件生态。</li><li>swc：定位是 Rust 版 Babel，支持大部分 Babel 常用插件与装饰器元数据（<code>design:type</code> 这类），Next.js 的编译与 Jest 的转换默认都在用它；迁移成本比 esbuild 低。</li><li>工程用法：webpack 里用 <code>esbuild-loader</code>/<code>swc-loader</code> 替换 <code>babel-loader</code>，压缩可用 <code>esbuild</code> 或 <code>TerserPlugin</code> 的 esbuild minify（比 Terser 快一个数量级，压缩率略低一点）；Vite 的依赖预构建与 TS 转译也是 esbuild。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// webpack 里用 esbuild-loader 替代 babel-loader + TerserPlugin</span>
module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">module</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">rules</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token literal-property property">test</span><span class="token operator">:</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">\\.[jt]sx?$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">,</span> <span class="token literal-property property">include</span><span class="token operator">:</span> path<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>__dirname<span class="token punctuation">,</span> <span class="token string">&#39;src&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
      <span class="token literal-property property">use</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token literal-property property">loader</span><span class="token operator">:</span> <span class="token string">&#39;esbuild-loader&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">options</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">target</span><span class="token operator">:</span> <span class="token string">&#39;es2015&#39;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token literal-property property">optimization</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">minimizer</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token keyword">new</span> <span class="token class-name">EsbuildPlugin</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">target</span><span class="token operator">:</span> <span class="token string">&#39;es2015&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：换成 esbuild 后需要注意什么？答：类型检查消失了（CI 必须有 <code>tsc --noEmit</code>）、装饰器元数据与部分 proposal 语法可能不支持、source map 的列映射精度与 Babel 略有差异。</li><li>陷阱：说&quot;esbuild 快是因为 Rust/Go 是编译型语言&quot;就停住。同样重要的是&quot;它选择不做什么&quot;——不做类型检查、不做 polyfill、不兼容全部 Babel 插件。</li><li>追问：那为什么大型项目还在用 Babel？答：为了插件生态（自定义转换、按需引入、国际化提取）、装饰器与元数据支持、以及极少数语法的精确兼容；速度可以靠缓存与并行部分缓解。</li></ul><h3 id="q20-npm、yarn、pnpm-的-node-modules-结构有什么区别-什么是幽灵依赖" tabindex="-1"><a class="header-anchor" href="#q20-npm、yarn、pnpm-的-node-modules-结构有什么区别-什么是幽灵依赖" aria-hidden="true">#</a> Q20 npm、yarn、pnpm 的 <code>node_modules</code> 结构有什么区别？什么是幽灵依赖？</h3><p><strong>考察点</strong>：考依赖提升（hoisting）与软硬链接两种方案的差异，以及幽灵依赖、依赖分身这两个真实事故来源。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：npm/yarn 把依赖&quot;提升&quot;到顶层 <code>node_modules</code>，导致你可以引用未声明的包（幽灵依赖）和同包多版本（依赖分身）；pnpm 用全局内容寻址存储加硬链接，顶层只放直接依赖的符号链接，从而做到严格且省磁盘。</p></blockquote><ol><li>npm v2 是嵌套结构（每个包自带 <code>node_modules</code>），路径深、大量重复；npm v3 起改为扁平化提升，<code>node_modules</code> 顶层尽量平铺所有依赖，冲突版本才嵌套到自己的子树里。</li><li>幽灵依赖（Phantom Dependency）：因为是平铺的，你 <code>import &#39;lodash&#39;</code> 时即使 <code>package.json</code> 没声明 lodash，只要某个依赖装了它就能跑通——直到那个依赖升级或删掉，你的代码突然构建失败。</li><li>依赖分身（Doppelgänger）：A 依赖 lodash@4.17.20、B 依赖 lodash@4.17.21，提升后会出现两份，体积翻倍；React 出现双实例会直接报 hooks 错误。</li><li>pnpm 结构：全局有一个内容寻址存储（content-addressable store），同一版本的文件只存一份；<code>node_modules/.pnpm/&lt;包&gt;@&lt;版本&gt;/node_modules/&lt;包&gt;</code> 是真实目录（文件通过<strong>硬链接</strong>指向 store），顶层 <code>node_modules/&lt;包&gt;</code> 只是指向它的<strong>符号链接</strong>。</li><li>严格性：每个包自己的 <code>node_modules</code> 下只链接它声明过的依赖，所以未声明的包根本解析不到，幽灵依赖从机制上被杜绝；代价是某些&quot;偷偷用了未声明依赖&quot;的老库会直接报模块找不到（可用 <code>public-hoist-pattern</code>、<code>shamefully-hoist</code> 或 <code>node-linker=hoisted</code> 妥协，但等于放弃 pnpm 的核心优势）。</li><li>决策：新项目优先 pnpm（快、省磁盘、依赖严格，monorepo 支持也好）；yarn berry 的 PnP 更强但生态兼容成本高；必须兼容老流程时 npm 也够用，关键是<strong>固定一个并让 CI 与本地一致</strong>。</li></ol><div class="language-jsonc line-numbers-mode" data-ext="jsonc"><pre class="language-jsonc"><code>// pnpm 遇到&quot;未声明依赖&quot;的老库时，最小妥协方案（不要全局 shamefully-hoist）
// .npmrc
public-hoist-pattern[]=*eslint*
public-hoist-pattern[]=*prettier*
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>npm ls lodash</code> 与 <code>pnpm why lodash</code> 有什么用？答：查某个包被谁引入、装了几个版本，是排查&quot;体积突然变大&quot;&quot;React 双实例&quot;的第一步。</li><li>陷阱：以为 pnpm 的硬链接等于复制。修改 <code>node_modules</code> 里的文件会影响 store 里的同一份内容，所以不要手改 <code>node_modules</code> 里的代码（要改用 <code>patch-package</code> 或 <code>pnpm patch</code>）。</li><li>追问：CI 上安装依赖为什么必须用锁定安装？答：<code>npm ci</code>/<code>pnpm i --frozen-lockfile</code> 严格按 lockfile 安装且不允许修改，保证本地、CI、生产是同一棵依赖树；否则出现&quot;CI 能过、线上报错&quot;。</li></ul><h3 id="q21-lockfile-有什么用-语义化版本和依赖升级策略怎么定" tabindex="-1"><a class="header-anchor" href="#q21-lockfile-有什么用-语义化版本和依赖升级策略怎么定" aria-hidden="true">#</a> Q21 lockfile 有什么用？语义化版本和依赖升级策略怎么定？</h3><p><strong>考察点</strong>：考 lockfile 的可复现价值、semver 范围符号的具体含义，以及团队级的升级策略（这是很多候选人答不出来的一题）。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：lockfile 记录每个依赖的<strong>精确版本与完整性校验值</strong>，保证任何人任何机器装出同一棵依赖树；semver 决定允许自动升级的范围，<code>^</code> 允许次版本升级、<code>~</code> 只允许补丁升级，升级策略要区分 patch/minor 与 major。</p></blockquote><ol><li>lockfile：<code>package-lock.json</code>/<code>yarn.lock</code>/<code>pnpm-lock.yaml</code> 包含解析后的版本、<code>resolved</code> 地址与 <code>integrity</code> 哈希；必须提交到仓库，CI 用 <code>npm ci</code> 或 <code>pnpm i --frozen-lockfile</code> 严格按它安装。</li><li>为什么需要：<code>package.json</code> 里的 <code>^1.2.3</code> 只是范围，别人下周安装可能装到 <code>1.5.0</code>，行为不一致；lockfile 把&quot;范围&quot;收敛成&quot;确定值&quot;，让构建可复现。</li><li>semver：<code>MAJOR.MINOR.PATCH</code>。<code>^1.2.3</code> 等价 <code>&gt;=1.2.3 &lt;2.0.0</code>；<code>~1.2.3</code> 等价 <code>&gt;=1.2.3 &lt;1.3.0</code>；<code>1.2.x</code>、<code>*</code>、<code>latest</code> 都过于宽松；<strong>0.x 例外</strong>——<code>^0.2.3</code> 只等价 <code>&gt;=0.2.3 &lt;0.3.0</code>，因为 0.x 视为不稳定。</li><li>依赖类型：<code>dependencies</code>（运行时需要，会进产物）、<code>devDependencies</code>（构建/测试用，不进产物）、<code>peerDependencies</code>（库要求宿主提供，如 react，npm 7+ 会自动安装）、<code>optionalDependencies</code>（可选，装不上不报错）。</li><li>升级策略：patch/minor 可以批量升并依赖 CI 回归；major 必须单独评估 changelog 与破坏性变更；用 Dependabot/Renovate 定时提 PR，把升级变成常规动作而不是&quot;攒一年再升一次&quot;。</li><li>强制统一版本：<code>overrides</code>（npm 8+）、<code>resolutions</code>（yarn）、<code>pnpm.overrides</code> 可以强制把传递依赖的版本收敛到指定版本，用来消灭依赖分身；<code>npm audit</code>/<code>pnpm audit</code> 定期查已知漏洞。</li></ol><div class="language-jsonc line-numbers-mode" data-ext="jsonc"><pre class="language-jsonc"><code>// package.json：强制统一 lodash 版本，消灭分身
{
  &quot;pnpm&quot;: { &quot;overrides&quot;: { &quot;lodash@&lt;4.17.21&quot;: &quot;4.17.21&quot; } }
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>陷阱：删掉 lockfile 重装来&quot;解决冲突&quot;。这会随机漂移几十个包版本，问题更难查；正确做法是 <code>pnpm why</code> 定位来源再 overrides。</li><li>追问：为什么 <code>^</code> 在 0.x 上不生效？答：semver 规定 0.x 是初始开发阶段，任何次版本都可能有破坏性变更，所以 <code>^0.2.3</code> 被收窄为 <code>&lt;0.3.0</code>。</li><li>追问：<code>dependencies</code> 和 <code>devDependencies</code> 放错会怎样？答：构建工具放 dependencies 会让 Docker 生产镜像多装一堆无用包、前端产物分析也变乱；反之把运行时需要的包放 devDependencies，某些部署流程（<code>npm i --production</code>）下直接运行失败。</li></ul><h3 id="q22-monorepo-怎么落地-pnpm-workspace-和-turborepo-各解决什么" tabindex="-1"><a class="header-anchor" href="#q22-monorepo-怎么落地-pnpm-workspace-和-turborepo-各解决什么" aria-hidden="true">#</a> Q22 Monorepo 怎么落地？pnpm workspace 和 Turborepo 各解决什么？</h3><p><strong>考察点</strong>：考是否做过真实的 monorepo：包之间怎么链接、任务怎么编排、变更影响怎么分析、版本怎么发布。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：pnpm workspace 解决&quot;多个包在同一个仓库里如何互相引用与统一安装&quot;，Turborepo/Nx 解决&quot;任务依赖顺序与缓存复用&quot;，Changesets 解决&quot;多包版本与 changelog 怎么发&quot;。</p></blockquote><ol><li>基座：<code>pnpm-workspace.yaml</code> 里声明 <code>packages: [&#39;packages/*&#39;, &#39;apps/*&#39;]</code>，各子包通过 <code>&quot;ui&quot;: &quot;workspace:*&quot;</code> 引用本地包，pnpm 会直接符号链接到源码目录，改一处立刻全局可见，无需 <code>npm link</code>。</li><li>收益：跨包重构可以原子提交（一次 PR 改完接口与所有调用方）、共享 lint/tsconfig/构建配置、类型定义直接复用、依赖只装一份。</li><li>任务编排：Turborepo 的核心是任务图与缓存。<code>turbo.json</code> 里 <code>&quot;build&quot;: { &quot;dependsOn&quot;: [&quot;^build&quot;], &quot;outputs&quot;: [&quot;dist/**&quot;] }</code> 表示&quot;先构建依赖的包，再构建自己&quot;；输入哈希不变时直接复用本地或远程缓存，跳过执行。</li><li>变更影响分析：<code>turbo run test --filter=...[origin/main]</code> 只对受影响的包及其下游跑任务；CI 里配合 <code>--affected</code> 能大幅缩短流水线时间，这是 monorepo 能否用起来的关键。</li><li>发布：Changesets 的流程是——开发者在 PR 里补一个 changeset（说明改了什么、是 patch/minor/major）→ 合并后由机器人汇总提升版本、生成 CHANGELOG、统一发布；比手工改版本号可靠得多。</li><li>难点与坑：React/Vue 单实例（<code>peerDependencies</code> + overrides 保证只有一份）、包内 TS 的 <code>paths</code> 与构建产物 <code>dist</code> 的类型指向（<code>exports</code>/<code>types</code> 字段要写对）、循环依赖（A 引 B、B 引 A 会让任务图成环）、以及&quot;改了 A 忘了重新构建 B&quot;导致的假成功（靠 <code>^build</code> 依赖规避）。</li></ol><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># turbo.json</span>
<span class="token punctuation">{</span>
  <span class="token key atrule">&quot;$schema&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;https://turbo.build/schema.json&quot;</span><span class="token punctuation">,</span>
  <span class="token key atrule">&quot;tasks&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">{</span>
    <span class="token key atrule">&quot;build&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">&quot;dependsOn&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;^build&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token key atrule">&quot;outputs&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;dist/**&quot;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token key atrule">&quot;test&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">&quot;dependsOn&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;build&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token key atrule">&quot;outputs&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;coverage/**&quot;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token key atrule">&quot;lint&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：monorepo 和&quot;多个仓库 + 私有 npm 包&quot;怎么选？答：看耦合度与协作频率。共享代码多、需要原子重构就 monorepo；团队边界清晰、发布节奏独立、仓库体量已影响克隆与 CI 速度时，多仓库反而更清爽。</li><li>陷阱：以为用了 pnpm workspace 就有缓存与增量。workspace 只解决链接与安装，任务编排与缓存是 Turborepo/Nx 的职责，不配就是每次全量构建。</li><li>追问：远程缓存（remote cache）的意义？答：CI 上算过的哈希结果可以回填到远端，本地和不同机器直接命中，把&quot;改一行跑十分钟&quot;变成几秒钟；要注意缓存污染与密钥隔离。</li></ul><h3 id="q23-eslint、prettier、stylelint-怎么分工-为什么总打架" tabindex="-1"><a class="header-anchor" href="#q23-eslint、prettier、stylelint-怎么分工-为什么总打架" aria-hidden="true">#</a> Q23 ESLint、Prettier、stylelint 怎么分工？为什么总打架？</h3><p><strong>考察点</strong>：考三类工具职责边界与冲突根因，以及&quot;配置放哪、忽略什么、CI 怎么卡&quot;这三个落地细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：ESLint 管代码质量与潜在缺陷，Prettier 只管格式，stylelint 管样式；打架的根因是两者都定义了格式规则，用 <code>eslint-config-prettier</code> 关掉 ESLint 的格式类规则即可，且它必须放在 <code>extends</code> 最后。</p></blockquote><ol><li>分工：ESLint 检查语义问题（未使用变量、<code>==</code>、hooks 依赖、import 顺序、<code>no-floating-promises</code>）；Prettier 只负责换行、缩进、引号、分号、尾逗号这类&quot;排版&quot;，不做任何语义判断；stylelint 管 CSS/SCSS/Less 的属性顺序与规范（可配 <code>stylelint-config-prettier</code> 关掉格式冲突）。</li><li>冲突根因：比如 ESLint 的 <code>indent</code>/<code>quotes</code> 与 Prettier 的默认风格不一致，<code>eslint --fix</code> 和 <code>prettier --write</code> 会互相改回去，形成&quot;拉锯&quot;。</li><li>标准解法：<code>extends: [&#39;eslint:recommended&#39;, &#39;plugin:vue/vue3-recommended&#39;, &#39;prettier&#39;]</code>——<code>eslint-config-prettier</code>（在 extends 里写 <code>&#39;prettier&#39;</code>）关掉所有与 Prettier 冲突的规则，<strong>必须放最后</strong>，否则前面的配置会重新打开它们。</li><li>两种协作模式：一是&quot;各管各的&quot;（推荐），ESLint 跑质量、Prettier 单独跑格式，编辑器和 CI 各跑一次；二是 <code>eslint-plugin-prettier</code> 把 Prettier 当 ESLint 规则跑（一次命令解决，但报错噪音大、速度慢，大项目不推荐）。</li><li>落地细节：<code>.eslintignore</code>/<code>ignorePatterns</code> 排除 <code>dist</code>、<code>node_modules</code>、<code>public</code>；Vue 用 <code>eslint-plugin-vue</code> + <code>vue-eslint-parser</code>，TypeScript 交给 <code>typescript-eslint</code>；ESLint 9 起默认使用扁平配置 <code>eslint.config.js</code>，替代 <code>.eslintrc</code>。</li><li>CI 卡口：<code>eslint --max-warnings=0</code>（有警告也失败），<code>prettier --check</code>（只校验不修改），避免&quot;CI 上自动改了代码但没人提交&quot;。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// eslint.config.js（ESLint 9 扁平配置，Prettier 相关配置放最后）</span>
<span class="token keyword">import</span> js <span class="token keyword">from</span> <span class="token string">&#39;@eslint/js&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">import</span> prettier <span class="token keyword">from</span> <span class="token string">&#39;eslint-config-prettier&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token punctuation">[</span>
  js<span class="token punctuation">.</span>configs<span class="token punctuation">.</span>recommended<span class="token punctuation">,</span>
  <span class="token operator">...</span>pluginVue<span class="token punctuation">.</span>configs<span class="token punctuation">[</span><span class="token string">&#39;flat/recommended&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">ignores</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;dist/**&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;node_modules/**&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  prettier<span class="token punctuation">,</span> <span class="token comment">// 必须最后，用于关闭格式类规则</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：编辑器保存时 Prettier 格式化、ESLint 又报格式错怎么办？答：在编辑器把 <code>editor.formatOnSave</code> 交给 Prettier、<code>codeActionsOnSave</code> 只留 ESLint 的 <code>source.fixAll.eslint</code> 且确保 <code>eslint-config-prettier</code> 生效，冲突就消失了。</li><li>陷阱：把 <code>eslint-config-prettier</code> 写在 <code>extends</code> 数组中间。后面的 <code>plugin:vue/...</code> 会把它关掉的规则再打开，表现为&quot;配了没用&quot;。</li><li>追问：老项目规则几千条警告，怎么推得动？答：先只对新文件生效（<code>overrides</code> 或 lint-staged 只查增量），历史代码用 <code>/* eslint-disable */</code> 或分批清理，一步到位改全部必然被抵制。</li></ul><h3 id="q24-husky、lint-staged、commitlint-怎么配合-git-分支模型和提交规范怎么定" tabindex="-1"><a class="header-anchor" href="#q24-husky、lint-staged、commitlint-怎么配合-git-分支模型和提交规范怎么定" aria-hidden="true">#</a> Q24 husky、lint-staged、commitlint 怎么配合？Git 分支模型和提交规范怎么定？</h3><p><strong>考察点</strong>：考提交前质量门禁的实现细节与 Git 协作模型，重点是&quot;为什么用 lint-staged 而不是全量 lint&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：husky 提供 Git 钩子，在 <code>pre-commit</code> 里用 lint-staged 只对暂存文件跑 lint/format，在 <code>commit-msg</code> 里用 commitlint 校验提交信息格式；分支模型上中小团队用 GitHub Flow（main + 短分支 + PR）配语义化提交即可。</p></blockquote><ol><li>husky：通过 Git 的 <code>core.hooksPath</code> 机制把钩子目录指向 <code>.husky</code>，v9 用 <code>npx husky init</code> 生成 <code>.husky/pre-commit</code>，文件里直接写命令（不再需要 shell 脚本头），无需手工改 <code>.git/hooks</code>。</li><li>lint-staged：只处理 <code>git add</code> 过的文件，把&quot;全量 lint 大项目要几十秒&quot;变成&quot;只查改动的几个文件，几百毫秒&quot;。配置写在 <code>package.json</code> 的 <code>lint-staged</code> 字段或 <code>.lintstagedrc</code>。</li><li>commitlint：在 <code>commit-msg</code> 钩子里校验提交信息，配 <code>@commitlint/config-conventional</code> 强制 Conventional Commits：<code>type(scope): subject</code>，type 取 <code>feat/fix/docs/style/refactor/perf/test/build/ci/chore/revert</code>。</li><li>价值：feat/fix 类型能自动生成 CHANGELOG、推断语义化版本号（配 semantic-release 或 Changesets），也能让 <code>git log</code> 变成可读的变更史。</li><li>钩子分类：<code>pre-commit</code>（提交前检查）、<code>commit-msg</code>（校验信息）、<code>pre-push</code>（推送前跑测试，耗时操作放这里而不是 pre-commit，否则提交变慢会逼着大家用 <code>--no-verify</code> 绕过）。</li><li>分支模型：Git Flow（main/develop/feature/release/hotfix，流程重，适合有固定发版周期的团队）；GitHub Flow（main 常绿 + 功能分支 + PR 合并，简单，推荐）；主干开发（Trunk Based，短分支 + 特性开关，配合强 CI）。发布用 tag 标记，回滚能精确定位到某次提交。</li></ol><div class="language-jsonc line-numbers-mode" data-ext="jsonc"><pre class="language-jsonc"><code>// package.json
{
  &quot;scripts&quot;: { &quot;prepare&quot;: &quot;husky&quot; },
  &quot;lint-staged&quot;: {
    &quot;*.{js,ts,vue}&quot;: [&quot;eslint --fix --max-warnings=0&quot;, &quot;prettier --write&quot;],
    &quot;*.{css,scss}&quot;: [&quot;stylelint --fix&quot;],
    &quot;*.md&quot;: [&quot;prettier --write&quot;]
  }
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># .husky/pre-commit</span>
npx lint-staged

<span class="token comment"># .husky/commit-msg</span>
npx <span class="token parameter variable">--no</span> -- commitlint <span class="token parameter variable">--edit</span> <span class="token string">&quot;<span class="token variable">$1</span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：钩子能被绕过，那还有意义吗？答：有，钩子是&quot;降低犯错概率&quot;的快速反馈；真正的卡口必须在 CI 上再跑一遍（<code>eslint</code>、<code>prettier --check</code>、对最近一次提交跑 commitlint），否则一个 <code>--no-verify</code> 就洞穿了。</li><li>陷阱：把单元测试放进 <code>pre-commit</code>。跑一次要几十秒，团队很快集体用 <code>--no-verify</code>，规范名存实亡；重活放 <code>pre-push</code> 或 CI。</li><li>追问：为什么提交规范值得强制？答：它让&quot;版本号、CHANGELOG、影响范围&quot;都能自动推导，也让线上问题回溯时能按 <code>fix</code>/<code>feat</code> 快速筛出可疑提交，是低成本高回报的约定。</li><li>追问：Windows 上钩子不生效怎么办？答：检查 <code>core.hooksPath</code> 是否被改过、<code>.husky</code> 目录是否被 <code>.gitignore</code> 误伤、以及行尾符（CRLF）问题；husky v9 已移除对 shell 脚本头的依赖，多数老问题不再出现。</li></ul><h3 id="q25-前端-ci-cd-流水线怎么搭-每一段在防什么" tabindex="-1"><a class="header-anchor" href="#q25-前端-ci-cd-流水线怎么搭-每一段在防什么" aria-hidden="true">#</a> Q25 前端 CI/CD 流水线怎么搭？每一段在防什么？</h3><p><strong>考察点</strong>：考流水线的分段设计与关键工程细节（锁定安装、缓存、构建一次多环境晋升、密钥隔离），而不是背 YAML 语法。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：前端流水线固定是&quot;装依赖 → 静态检查 → 测试 → 构建 → 部署&quot;五段，每一段都是一个卡口；核心工程原则是锁定安装保证可复现、缓存加速、构建产物传递而不是重复构建、密钥只进构建环境不进产物。</p></blockquote><ol><li>触发条件：PR 只跑检查与测试（快反馈），合并到主干后构建并部署测试环境，打 tag 时发布生产；这样既能挡住坏代码，又不会让每个 PR 都产生部署。</li><li>装依赖：必须 <code>npm ci</code>/<code>pnpm i --frozen-lockfile</code>，禁止在 CI 里更新 lockfile；配 <code>actions/setup-node</code> 的 <code>cache: pnpm</code> 或 <code>actions/cache</code> 缓存依赖与构建缓存，能省掉一半时间。</li><li>静态检查：<code>lint</code>、<code>prettier --check</code>、<code>tsc --noEmit</code>（类型检查）在这一段跑，失败即终止；与本地钩子不同，这里是不可绕过的强卡口。</li><li>测试：单元/组件测试带覆盖率，<code>--coverage</code> 上传报告并设阈值；E2E 放独立 job（耗时长）并分片并行，只在主干或发布分支运行。</li><li>构建：<code>pnpm build</code> 产出 <code>dist</code>，用 artifact 上传给后续部署 job 复用——<strong>构建一次、多环境晋升</strong>，避免&quot;测试环境构建的东西和生产构建的东西不是同一份&quot;。</li><li>部署：通过 Secrets/Environments 注入环境变量，上传 CDN/对象存储并刷新缓存，或推送镜像；密钥只存在于流水线变量中，绝不能出现在构建产物里（前端产物是公开的）。</li></ol><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/ci.yml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> ci
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">pull_request</span><span class="token punctuation">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token key atrule">push</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">branches</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>main<span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">verify</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> pnpm/action<span class="token punctuation">-</span>setup@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">version</span><span class="token punctuation">:</span> <span class="token number">9</span> <span class="token punctuation">}</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/setup<span class="token punctuation">-</span>node@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">node-version</span><span class="token punctuation">:</span> <span class="token number">20</span><span class="token punctuation">,</span> <span class="token key atrule">cache</span><span class="token punctuation">:</span> pnpm <span class="token punctuation">}</span>
      <span class="token punctuation">-</span> <span class="token key atrule">run</span><span class="token punctuation">:</span> pnpm install <span class="token punctuation">-</span><span class="token punctuation">-</span>frozen<span class="token punctuation">-</span>lockfile
      <span class="token punctuation">-</span> <span class="token key atrule">run</span><span class="token punctuation">:</span> pnpm lint <span class="token important">&amp;&amp;</span> pnpm tsc <span class="token punctuation">-</span><span class="token punctuation">-</span>noEmit
      <span class="token punctuation">-</span> <span class="token key atrule">run</span><span class="token punctuation">:</span> pnpm test <span class="token punctuation">-</span><span class="token punctuation">-</span> <span class="token punctuation">-</span><span class="token punctuation">-</span>coverage
      <span class="token punctuation">-</span> <span class="token key atrule">run</span><span class="token punctuation">:</span> pnpm build
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/upload<span class="token punctuation">-</span>artifact@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> dist<span class="token punctuation">,</span> <span class="token key atrule">path</span><span class="token punctuation">:</span> dist <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不每个环境各构建一次？答：构建三次就是三份不同的产物（依赖解析、时间戳、变量替换都可能不同），线上问题无法在测试环境复现。正确做法是同一份产物配不同运行时配置。</li><li>陷阱：把 <code>.env.production</code> 里的 API 地址在 CI 里用 <code>sed</code> 改源码再构建。这会污染仓库与哈希，且多环境产物不一致；应该用运行时配置或构建参数。</li><li>追问：GitLab CI 怎么对应？答：<code>stages: [install, lint, test, build, deploy]</code>，用 <code>cache: { key: $CI_COMMIT_REF_SLUG, paths: [node_modules, .pnpm-store] }</code> 缓存，<code>artifacts: paths: [dist]</code> 在 stage 之间传产物，用 <code>rules</code> 控制触发条件。</li></ul><h3 id="q26-多环境配置怎么注入-运行时配置和构建时注入有什么区别" tabindex="-1"><a class="header-anchor" href="#q26-多环境配置怎么注入-运行时配置和构建时注入有什么区别" aria-hidden="true">#</a> Q26 多环境配置怎么注入？运行时配置和构建时注入有什么区别？</h3><p><strong>考察点</strong>：考&quot;构建时替换 vs 运行时读取&quot;的差异与代价，这是最容易把密钥误打包的地方。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：构建时注入（DefinePlugin/<code>import.meta.env</code>）是把值当字面量替换进代码，简单但一份产物只能对应一个环境、且值会暴露在 JS 里；运行时注入是把配置放在独立文件或接口里，部署时替换，一份产物可跑多环境。</p></blockquote><ol><li>构建时注入（Webpack）：<code>new webpack.DefinePlugin({ &#39;process.env.API_BASE&#39;: JSON.stringify(url) })</code> 做的是文本替换，值必须 <code>JSON.stringify</code>，否则字符串被当表达式解析；它只在匹配文件里替换，<code>node_modules</code> 默认不处理。</li><li>构建时注入（Vite）：只用 <code>import.meta.env.VITE_*</code>，变量在构建时被静态替换，<code>import.meta.env[key]</code> 这类动态访问无效。</li><li>代价：每个环境都要构建一次（哈希不同、缓存失效），且变量明文躺在 JS 里——<strong>前端没有秘密</strong>，前缀机制只是提醒你&quot;这个值会公开&quot;。</li><li>运行时配置方案一：<code>public/config.js</code> 里写 <code>window.__APP_CONFIG__ = { apiBase: &#39;...&#39; }</code>，并在 <code>index.html</code> 中先于业务脚本引入；部署时只替换这个文件（Docker 常用 entrypoint 脚本按环境变量渲染它）。</li><li>运行时配置方案二：启动时 <code>fetch(&#39;/config.json&#39;)</code> 拉配置再挂载；配置可热改、无需重新构建，代价是多一次请求且要处理&quot;配置没到就渲染&quot;的时序问题。</li><li>落地建议：技术令牌、内部域名这类敏感值一律不给前端，改由后端接口下发；环境地址、开关、埋点 ID 这类公开值用运行时配置，做到&quot;构建一次、到处部署&quot;。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// webpack：构建时注入，值必须序列化</span>
<span class="token keyword">new</span> <span class="token class-name">webpack<span class="token punctuation">.</span>DefinePlugin</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token string-property property">&#39;process.env.NODE_ENV&#39;</span><span class="token operator">:</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span><span class="token string">&#39;production&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                           <span class="token literal-property property">__API_BASE__</span><span class="token operator">:</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span><span class="token string">&#39;https://api.example.com&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>

<span class="token comment">// public/config.js：运行时注入，部署时替换，不用重新构建</span>
window<span class="token punctuation">.</span>__APP_CONFIG__ <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">apiBase</span><span class="token operator">:</span> <span class="token string">&#39;https://api.example.com&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">sentryDsn</span><span class="token operator">:</span> <span class="token string">&#39;&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>陷阱：在 <code>VITE_</code>/<code>REACT_APP_</code> 变量里写数据库密码或第三方私钥。产物是公开文件，任何人 View Source 都能读到，这不是&quot;配置疏漏&quot;而是安全事故。</li><li>追问：Webpack 5 里 <code>process.env</code> 为什么报错未定义？答：webpack 5 不再自动为浏览器 polyfill <code>process</code>；要么用 DefinePlugin 精确替换用到的字段，要么 <code>resolve.fallback.process = &#39;process/browser&#39;</code>（代价是打进一个垫片）。</li><li>追问：<code>config.js</code> 被 CDN 缓存了怎么办？答：给它设短缓存（<code>no-cache</code>）或加带版本号的 query/文件名，且不要与哈希化的静态资源走同一套长缓存策略。</li><li>追问：如何确认密钥没被打进产物？答：构建后在 <code>dist</code> 里 grep 关键字段（或用脚本在 CI 里做一次断言），比&quot;我觉得没有&quot;可靠。</li></ul><h3 id="q27-前端怎么发布上线-cdn、nginx、docker-各自要注意什么" tabindex="-1"><a class="header-anchor" href="#q27-前端怎么发布上线-cdn、nginx、docker-各自要注意什么" aria-hidden="true">#</a> Q27 前端怎么发布上线？CDN、Nginx、Docker 各自要注意什么？</h3><p><strong>考察点</strong>：考完整的发布链路与缓存策略设计，以及灰度、回滚这些生产必备能力的具体做法。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：发布的核心是&quot;内容指纹化的静态资源长缓存 + <code>index.html</code> 不缓存&quot;，配合版本目录实现秒级回滚与灰度；Nginx 负责 history 路由与缓存头，Docker 用多阶段构建把产物塞进 nginx 镜像。</p></blockquote><ol><li>缓存策略：JS/CSS/图片带 <code>[contenthash]</code> 且内容变则名变，可设 <code>Cache-Control: public, max-age=31536000, immutable</code>；<code>index.html</code> 绝不能长缓存（<code>no-cache</code> 或 <code>max-age=0, must-revalidate</code>），否则用户永远拿不到新版——这是最高频的线上事故。</li><li>发布流程：构建产物按版本号归档（如 <code>/releases/1.2.3/</code>）→ 上传 CDN/对象存储 → 把 <code>index.html</code>（或 Nginx 的 alias 指向）切到新版本目录 → 刷新 CDN 上 <code>index.html</code> 的缓存；静态资源因路径带版本无需刷新。</li><li>灰度：按用户 ID/cookie/比例分流到不同版本目录（Nginx <code>map</code> + <code>if</code> 或网关层做），灰度期间后端接口必须同时兼容新旧前端；观察到错误率正常后再全量。</li><li>回滚：保留最近 N 个版本目录，回滚只改指针（切 <code>index.html</code> 或 Nginx 指向），<strong>不重新构建</strong>，因此是秒级操作；这也要求数据库/接口变更必须向后兼容。</li><li>Nginx 要点：SPA 用 <code>try_files $uri $uri/ /index.html;</code> 处理 history 路由；开 gzip/brotli；<code>/api</code> 反向代理要带 <code>proxy_set_header Host $host</code> 等头；注意 <code>root</code> 与 <code>alias</code> 的差异；补 CSP、<code>X-Content-Type-Options</code> 等安全头。</li><li>Docker 要点：多阶段构建——<code>node:20-alpine</code> 里装依赖并构建，再把 <code>dist</code> 拷进 <code>nginx:alpine</code>，镜像里没有源码与 <code>node_modules</code>；用 <code>.dockerignore</code> 排除 <code>node_modules</code>/<code>dist</code>；环境差异用 <code>--build-arg</code> 或挂载的 <code>config.js</code> 解决。</li></ol><div class="language-nginx line-numbers-mode" data-ext="nginx"><pre class="language-nginx"><code><span class="token directive"><span class="token keyword">server</span></span> <span class="token punctuation">{</span>
  <span class="token directive"><span class="token keyword">listen</span> <span class="token number">80</span></span><span class="token punctuation">;</span>
  <span class="token directive"><span class="token keyword">root</span> /usr/share/nginx/html</span><span class="token punctuation">;</span>
  <span class="token directive"><span class="token keyword">location</span> /</span> <span class="token punctuation">{</span>
    <span class="token directive"><span class="token keyword">try_files</span> <span class="token variable">$uri</span> <span class="token variable">$uri</span>/ /index.html</span><span class="token punctuation">;</span>       <span class="token comment"># history 路由</span>
    <span class="token directive"><span class="token keyword">add_header</span> Cache-Control <span class="token string">&quot;no-cache&quot;</span></span><span class="token punctuation">;</span>     <span class="token comment"># index.html 不缓存</span>
  <span class="token punctuation">}</span>
  <span class="token directive"><span class="token keyword">location</span> ~* \\.(js|css|png|woff2)$</span> <span class="token punctuation">{</span>
    <span class="token directive"><span class="token keyword">expires</span> <span class="token number">1y</span></span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">add_header</span> Cache-Control <span class="token string">&quot;public, max-age=31536000, immutable&quot;</span></span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token directive"><span class="token keyword">location</span> /api/</span> <span class="token punctuation">{</span> <span class="token directive"><span class="token keyword">proxy_pass</span> http://backend:3000/</span><span class="token punctuation">;</span> <span class="token directive"><span class="token keyword">proxy_set_header</span> Host <span class="token variable">$host</span></span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-docker line-numbers-mode" data-ext="docker"><pre class="language-docker"><code><span class="token instruction"><span class="token keyword">FROM</span> node:20-alpine <span class="token keyword">AS</span> build</span>
<span class="token instruction"><span class="token keyword">WORKDIR</span> /app</span>
<span class="token instruction"><span class="token keyword">COPY</span> package.json pnpm-lock.yaml ./</span>
<span class="token instruction"><span class="token keyword">RUN</span> corepack enable &amp;&amp; pnpm i --frozen-lockfile</span>
<span class="token instruction"><span class="token keyword">COPY</span> . .</span>
<span class="token instruction"><span class="token keyword">RUN</span> pnpm build</span>

<span class="token instruction"><span class="token keyword">FROM</span> nginx:alpine</span>
<span class="token instruction"><span class="token keyword">COPY</span> <span class="token options"><span class="token property">--from</span><span class="token punctuation">=</span><span class="token string">build</span></span> /app/dist /usr/share/nginx/html</span>
<span class="token instruction"><span class="token keyword">COPY</span> nginx.conf /etc/nginx/conf.d/default.conf</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么静态资源敢缓存一年？答：文件名里带内容哈希，内容一变文件名就变，URL 也就变了，浏览器会当成新资源请求；所谓&quot;缓存一年&quot;缓存的是永远不会变的那份内容。</li><li>陷阱：<code>index.html</code> 也设了长缓存并上传了 CDN。用户会一直加载旧 HTML，而旧 HTML 引用的是旧哈希资源，于是&quot;发版了但用户还是旧版本&quot;，且刷新也无效——只能等缓存过期或手动刷 CDN。</li><li>追问：部署到子路径 <code>/admin/</code> 要改哪些地方？答：构建的 <code>publicPath</code>（Webpack）/<code>base</code>（Vite）、路由的 <code>base</code>、Nginx 的 <code>location /admin/</code> 与 <code>alias</code>，三处必须一致，漏一处就是 404 或白屏。</li></ul><h3 id="q28-前端自动化测试体系怎么分层-覆盖率和投入产出怎么算" tabindex="-1"><a class="header-anchor" href="#q28-前端自动化测试体系怎么分层-覆盖率和投入产出怎么算" aria-hidden="true">#</a> Q28 前端自动化测试体系怎么分层？覆盖率和投入产出怎么算？</h3><p><strong>考察点</strong>：考测试金字塔的实践判断（哪些值得测、E2E 怎么控成本），而不是罗列框架名。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：按测试金字塔分层——大量快的单元测试覆盖纯逻辑，适量组件/集成测试覆盖用户行为，少量 E2E 覆盖登录支付等关键流程；覆盖率是参考指标而非目标，追求 100% 是低回报投入。</p></blockquote><ol><li>单元测试：测纯函数、工具方法、composable/hooks、store 的 reducer，快且无环境依赖，数量应最多，是重构的安全网。</li><li>组件/集成测试：用 Testing Library 渲染组件、模拟用户操作与网络（MSW 拦截请求），断言用户可见的结果（按钮文案、可访问性角色）而不是内部状态；这类测试最能反映&quot;功能真的坏了没有&quot;。</li><li>E2E 测试：Playwright/Cypress 跑真实浏览器，覆盖登录、下单、支付等核心流程；最贴近真实但慢且脆，只测关键路径并限制数量。</li><li>工具选型：Jest（生态成熟、配置较重）与 Vitest（复用 Vite 配置、更快，API 基本兼容 Jest）；E2E 选 Playwright（跨浏览器、自动等待、trace 回放）或 Cypress（调试体验好）。</li><li>覆盖率：分 statements/branches/functions/lines 四项，<code>coverageThreshold</code> 对核心目录设阈值（如 60%-80%）；它只说明&quot;这行被执行过&quot;，不说明断言有效，别当 KPI。</li><li>投入产出：优先给&quot;改得频繁 + 出错代价高&quot;的模块写测试（金额计算、权限判断、表单校验），纯展示组件不写；测试要可重复——用 <code>findBy*</code> 异步查询而不是 <code>sleep</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// Vitest + Testing Library：断言用户能看到什么，而不是组件内部状态</span>
<span class="token keyword">import</span> <span class="token punctuation">{</span> render<span class="token punctuation">,</span> screen <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@testing-library/vue&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">import</span> userEvent <span class="token keyword">from</span> <span class="token string">&#39;@testing-library/user-event&#39;</span><span class="token punctuation">;</span>

<span class="token function">test</span><span class="token punctuation">(</span><span class="token string">&#39;点击加一按钮后显示 1&#39;</span><span class="token punctuation">,</span> <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token function">render</span><span class="token punctuation">(</span>Counter<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">await</span> userEvent<span class="token punctuation">.</span><span class="token function">click</span><span class="token punctuation">(</span>screen<span class="token punctuation">.</span><span class="token function">getByRole</span><span class="token punctuation">(</span><span class="token string">&#39;button&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;加一&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token function">expect</span><span class="token punctuation">(</span>screen<span class="token punctuation">.</span><span class="token function">getByText</span><span class="token punctuation">(</span><span class="token string">&#39;当前：1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toBeTruthy</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：E2E 经常因环境不稳定挂掉，怎么治？答：用自动等待代替固定 <code>sleep</code>、测试数据自建自清、接口开稳定桩数据、失败重试并保存 trace，同时把 E2E 与单元测试拆成不同 job。</li><li>陷阱：为每个组件写快照测试。快照会随任何改动更新，<code>-u</code> 一按就&quot;通过&quot;，除了制造维护负担几乎抓不到 bug。</li><li>追问：TypeScript 项目测试怎么写类型？答：测试文件纳入 <code>tsconfig</code> 或单独一份测试配置；用 <code>vitest/globals</code> 或显式 import 避免全局类型报错，<code>tsc --noEmit</code> 也要覆盖测试目录。</li><li>追问：没有测试的项目怎么开始？答：先给一个最近改过且出过 bug 的纯函数模块补上，跑进 CI 形成习惯，再往组件与关键流程扩。</li></ul><h3 id="q29-你们项目的脚手架和模板工程里应该预置什么" tabindex="-1"><a class="header-anchor" href="#q29-你们项目的脚手架和模板工程里应该预置什么" aria-hidden="true">#</a> Q29 你们项目的脚手架和模板工程里应该预置什么？</h3><p><strong>考察点</strong>：考&quot;工程化落地&quot;的经验：模板里哪些东西是必须项，以及模板长期维护这个常被忽略的问题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：脚手架的价值是把团队约定一次性固化，新项目开箱即用；模板里至少要预置构建、规范、多环境、请求层、目录约定、CI 与部署配置，并且必须指定维护人和升级机制。</p></blockquote><ol><li>技术底座：框架版本 + TypeScript + 路径别名（<code>@/</code>）+ 编辑器配置（<code>.editorconfig</code>、<code>.vscode/settings.json</code> 统一保存格式化行为），避免&quot;每个人格式不同导致 diff 噪音大&quot;。</li><li>规范体系：ESLint + Prettier + stylelint + husky + lint-staged + commitlint 全套装好并跑通一次，让新人在第一次提交时就接受规范。</li><li>构建与多环境：<code>.env.development/.env.staging/.env.production</code>、代理配置、产物目录与 <code>base/publicPath</code>，以及区分 dev/build 的 source map 策略。</li><li>运行时骨架：请求层封装（统一 baseURL、拦截器、错误码与 token 刷新）、路由与权限骨架、状态管理、全局错误上报（Sentry 之类）、基础布局与主题变量。</li><li>交付配置：CI 流水线文件（lint/test/build）、Dockerfile + nginx.conf、<code>.dockerignore</code>、README（目录结构与命令说明）、以及 <code>.gitignore</code>（排除 <code>.env.local</code>、<code>node_modules</code>、<code>dist</code>）。</li><li>生成方式与维护：官方模板（<code>create-vue</code>、<code>create-vite</code>）优先，团队内用自研 CLI（<code>commander</code>/<code>prompts</code> 交互 + <code>degit</code> 拉模板仓库 + 变量替换）做二次封装；关键是要有版本号与升级路径（模板发新版、老项目按 changelog 增量同步），否则半年后模板腐化，没人敢用。</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 自研脚手架的最小骨架</span>
npx degit my-org/templates/vue3-ts<span class="token comment">#v1.4.0 my-app   # 拉指定版本模板</span>
<span class="token builtin class-name">cd</span> my-app <span class="token operator">&amp;&amp;</span> <span class="token function">pnpm</span> i <span class="token operator">&amp;&amp;</span> <span class="token function">pnpm</span> dlx husky init <span class="token operator">&amp;&amp;</span> <span class="token function">pnpm</span> dev
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：用官方 <code>create-vue</code> 还是自研 CLI？答：先基于官方模板做团队定制（fork 或 <code>degit</code>），只有定制项足够多、且需要交互式选择（要不要 E2E、要不要 i18n）时才值得自研，自己写模板引擎通常得不偿失。</li><li>陷阱：模板里锁死一堆过时依赖就不管了。模板更新一次能同时惠及所有新项目，必须像维护公共库一样给它排版本与升级窗口。</li><li>追问：怎么让老项目也用上模板的新能力？答：把模板拆成可独立同步的几块（lint 配置包、请求层 npm 包、CI 片段），老项目按需升级对应包，而不是整体重新生成项目。</li></ul><h3 id="q30-你遇到过的构建事故有哪些-怎么排查" tabindex="-1"><a class="header-anchor" href="#q30-你遇到过的构建事故有哪些-怎么排查" aria-hidden="true">#</a> Q30 你遇到过的构建事故有哪些？怎么排查？</h3><p><strong>考察点</strong>：考排障经验与&quot;从现象定位到根因&quot;的路径。能说出缓存未失效、<code>publicPath</code> 错、环境变量进产物这三类，并给出查证手段，才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：构建事故的根因大多落在四处——缓存与指纹、路径前缀、环境差异、依赖重复；排查顺序是&quot;用线上真实产物复现 → 看网络与报错 → 对比构建配置与依赖树&quot;。</p></blockquote><ol><li>缓存未失效：发版后用户仍是旧页面，或 JS 与 HTML 版本不匹配导致 <code>ChunkLoadError</code>。根因是 <code>index.html</code> 被长缓存，或用了 <code>[hash]</code> 让无关文件哈希全变；对策是 HTML 不缓存、资源用 <code>[contenthash]</code>，并保留旧版本目录一段时间。</li><li><code>publicPath</code>/<code>base</code> 配错：部署到子路径或 CDN 后资源 404、白屏，因为构建前缀与实际访问路径不一致，或路由 <code>base</code> 没同步改；排查就看 Network 里真实请求的 URL 前缀。</li><li>环境变量打包进产物：密钥写进 <code>VITE_*</code>/<code>REACT_APP_*</code> 就等于公开；前端只放公开配置，敏感值由接口下发，并在 CI 里 grep <code>dist</code> 做断言。</li><li>本地正常、CI 或线上失败：多为大小写敏感（Windows 不敏感、Linux 敏感，<code>import &#39;./Button&#39;</code> 找不到 <code>button.vue</code>）、Node 版本不一致、CJS/ESM 混用。</li><li>依赖相关：多版本共存导致体积翻倍或 React/Vue 双实例（hooks 报错、响应式失效），用 <code>npm ls</code>/<code>pnpm why</code> 定位后 overrides 收敛；缓存疑似脏了就清 <code>node_modules/.cache</code> 与构建缓存。</li><li>排查方法：用 <code>npx serve dist</code> 跑<strong>真实产物</strong>（dev server 复现不了缓存与路径问题），配合 bundle-analyzer 与 stats 对比上次成功的构建；构建内存溢出就加 <code>--max-old-space-size</code>、简化 source map。</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 线上白屏的三步定位：产物是否完整、请求是否 404、运行时是否报错</span>
<span class="token function">ls</span> dist <span class="token operator">&amp;&amp;</span> npx serve dist <span class="token parameter variable">-l</span> <span class="token number">5000</span>   <span class="token comment"># 用真实产物本地复现</span>
<span class="token function">grep</span> <span class="token parameter variable">-r</span> <span class="token string">&quot;VITE_&quot;</span> dist/assets <span class="token operator">|</span> <span class="token function">head</span>  <span class="token comment"># 检查变量是否被替换为字面量</span>
<span class="token function">pnpm</span> why react                        <span class="token comment"># 检查是否出现重复依赖</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>ChunkLoadError</code> 是什么原因？答：用户停留在旧 <code>index.html</code>，它引用的异步 chunk 已被新版本覆盖（文件名变了），按需加载即 404；对策是保留旧版本目录、给异步加载加重试。</li><li>陷阱：出问题先怀疑框架或工具版本，而不是先看&quot;上一次改了什么&quot;。构建事故大多归到缓存、路径、环境、依赖这四类，优先按这四条查。</li><li>追问：为什么必须用 <code>npx serve dist</code> 验证？答：dev server 是内存产物、无 CDN 缓存、无路径前缀，恰好绕过了事故的全部根因，真实产物才能复现。</li></ul><h2 id="本章小结" tabindex="-1"><a class="header-anchor" href="#本章小结" aria-hidden="true">#</a> 本章小结</h2><ul><li>工程化解决的是开发体验、协作规范、构建、发布、质量五类问题，工具只是手段；脚手架的价值在于把这些约定一次性固化并持续维护。</li><li>Webpack 里 <code>entry</code> 找依赖、<code>output</code> 定产物、<code>loader</code> 翻译模块（从右到左执行、只做文件级转换）、<code>plugin</code> 通过 tapable 钩子干预编译生命周期、<code>mode</code> 控制内置优化。</li><li>构建分三阶段：初始化建 <code>Compiler</code> 并挂插件，编译期用 loader 把模块递归解析成模块图，输出期切成 chunk、优化并写 assets；HMR 靠 WebSocket 通知加 hot-update 补丁做模块级替换，无人 accept 时退化为整页刷新。</li><li>tree-shaking 靠 ESM 静态结构标记、Terser 真正删除，必须配合 <code>sideEffects</code> 与 <code>mode: production</code>；code splitting 用动态 <code>import()</code> 与 <code>splitChunks</code>（记得 <code>chunks: &#39;all&#39;</code>），预取用 <code>prefetch</code>、预加载用 <code>preload</code>。</li><li>Vite 开发期用原生 ESM 按需编译加 esbuild 依赖预构建，生产期交给 Rollup；Webpack 生态更庞大、配置更可控，新项目优先 Vite、老项目与深度定制场景留在 Webpack。</li><li>语法降级与 API 补齐是两件事：Babel 转语法，core-js 补 API，regenerator 提供 async 运行时，<code>useBuiltIns: &#39;usage&#39;</code> 按需注入，browserslist 统一决定目标环境。</li><li>包管理上 pnpm 用内容寻址存储加硬链接做到严格、省磁盘、无幽灵依赖；lockfile 保证可复现安装，<code>^</code> 允许 minor 升级、<code>~</code> 只允许 patch，major 必须单独评估。</li><li>质量与交付链路是&quot;规范 → 检查 → 测试 → 构建 → 发布&quot;：lint-staged 只查增量、CI 不可绕过；资源用 contenthash 长缓存、<code>index.html</code> 不缓存，构建一次多环境晋升，回滚只切指针。</li></ul>`,246);function c(l,i){return s(),e("div",null,[p,a(" COUNT: 30 ")])}const r=n(t,[["render",c],["__file","17-engineering.html.vue"]]);export{r as default};
